window.OPERATION_SCREEN_BUNDLE = {"1P_1차측Purge_자동진행.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>1P 1차측 Purge 자동진행 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 1P 구간 - 1차측 Purge\" 화면 분리 파일 - Status \"1P\" 4개\n     서브시퀀스(1-2차측 Vent Mode → 2차측 Purge → Pumping → 1차측 Purge) 중 마지막(4번째).\n     Pumping(ns='onePPumping') 완료 직후 자동으로 시작된다(Operation.js의\n     showProgressCylExchangePurgeStep 특수 분기). 서브시퀀스 엑셀 엔진(gms-sub-sequence-runner.js,\n     ns='onePPrimaryPurge')으로 실행 - 실제 내용은 data/gmsSubSequences/OneP4_v1.json(배관진공\n     확인 → N2 Purge → 예약어 '진행횟수'로 CONFIG \"교환전 1차 퍼지진행 횟수\"만큼 반복,\n     2차측 Purge와 동일 패턴). 완료 시 1P 구간 전체가 끝나 Status가 -L(감압시험)로 넘어간다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressOnePPrimaryPurgeAutoRunBody\">\n    <div class=\"step-badges-lg\">\n      <span class=\"step-badge-lg blinking\">1P</span>\n      <span class=\"step-badge-lg\">-L</span>\n      <span class=\"step-badge-lg\" data-vt-badge>-VT</span>\n      <span class=\"step-badge-lg\">2P</span>\n    </div>\n\n    <div id=\"onePPrimaryPurgeIdle\">\n      <div class=\"progress-menu-desc\">1차측 Purge 구간을 준비하는 중입니다...</div>\n      <div class=\"sub-seq-last-alarm\" id=\"onePPrimaryPurgeLastAlarm\"></div>\n      <div class=\"purge-count-panel\" id=\"onePPrimaryPurgeIdleCycleInfo\" style=\"display:none;\">\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">설정 횟수 :</span>\n          <span class=\"purge-count-box\">[ <span id=\"onePPrimaryPurgeIdleCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">진행 횟수 :</span>\n          <span class=\"purge-count-box\">[ <span id=\"onePPrimaryPurgeIdleCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"onePPrimaryPurgeExecuteBtn\" style=\"margin:0;\">실행</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPrimaryPurgeIdleCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPrimaryPurgeIdleTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPrimaryPurgeIdleExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPrimaryPurgeIdleExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"onePPrimaryPurgeIdleExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n\n    <div id=\"onePPrimaryPurgePanel\" style=\"display:none;\">\n      <div class=\"sub-seq-step-label\" id=\"onePPrimaryPurgeStepLabel\">Main 1 - Sub 1</div>\n      <div class=\"sub-seq-operation\" id=\"onePPrimaryPurgeOperation\">-</div>\n      <div class=\"sub-seq-message\" id=\"onePPrimaryPurgeMessage\">-</div>\n      <div class=\"sub-seq-valve-diff\" id=\"onePPrimaryPurgeValveDiff\"></div>\n      <div class=\"sub-seq-timer\" id=\"onePPrimaryPurgeTimer\">-</div>\n      <div class=\"sub-seq-acc-time\" id=\"onePPrimaryPurgeAccTime\">누적 경과시간: 0초</div>\n      <div class=\"sub-seq-alarm-banner\" id=\"onePPrimaryPurgeAlarmBanner\" style=\"display:none;\">\n        <div class=\"sub-seq-last-alarm\" id=\"onePPrimaryPurgePanelAlarmMsg\"></div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"purge-count-panel\" id=\"onePPrimaryPurgeCycleInfo\" style=\"display:none;\">\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">설정 횟수 :</span>\n            <span class=\"purge-count-box\">[ <span id=\"onePPrimaryPurgeCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">진행 횟수 :</span>\n            <span class=\"purge-count-box\">[ <span id=\"onePPrimaryPurgeCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n        </div>\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"onePPrimaryPurgeAckBtn\" style=\"margin:0; display:none;\">확인</button>\n          <!-- 평소엔 \"취소\", 알람 배너가 떠 있는 동안엔 \"실행\"으로 바뀌어 재시작을 담당한다. -->\n          <!-- 테스트용 - 카운트다운/누적시간을 그 자리에서 멈추고 남은 시간부터 이어서\n               재개할 수 있다(사용자 요청). -->\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPrimaryPurgePauseBtn\" style=\"margin:0;\">일시정지</button>\n          <!-- 테스트 기간 전용 - Step 1부터 즉시 다시 시작한다(사용자 요청). -->\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPrimaryPurgeResetBtn\" style=\"margin:0;\">초기화</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPrimaryPurgeCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPrimaryPurgeTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <!-- 이 구간(1차측 Purge)에 연결된 서브시퀀스(OneP4_v1)를 엑셀로 내보내서 편집하고,\n             편집한 파일을 다시 불러와 그대로 반영한다(gms-sub-sequence-runner.js). -->\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPrimaryPurgeExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPrimaryPurgeExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"onePPrimaryPurgeExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","1P_2차측Purge_자동진행.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>1P 2차측 Purge 자동진행 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 1P 구간 - 2차측 Purge\" 화면 분리 파일 - Status \"1P\" 4개\n     서브시퀀스(1-2차측 Vent Mode → 2차측 Purge → Pumping → 1차측 Purge) 중 2번째. 1-2차측\n     Vent Mode(ns='oneP') 완료 직후 자동으로 시작된다(Operation.js의\n     showProgressCylExchangePurgeStep 특수 분기). 서브시퀀스 엑셀 엔진(gms-sub-sequence-runner.js,\n     ns='onePPurge')으로 실행 - 실제 내용은 data/gmsSubSequences/OneP2_v1.json(아직 뼈대,\n     밸브/조건 미정). 완료 시 자동으로 Pumping(onePPumping)으로 넘어간다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressOnePPurgeAutoRunBody\">\n    <div class=\"step-badges-lg\">\n      <span class=\"step-badge-lg blinking\">1P</span>\n      <span class=\"step-badge-lg\">-L</span>\n      <span class=\"step-badge-lg\" data-vt-badge>-VT</span>\n      <span class=\"step-badge-lg\">2P</span>\n    </div>\n\n    <div id=\"onePPurgeIdle\">\n      <div class=\"progress-menu-desc\">2차측 Purge 구간을 준비하는 중입니다...</div>\n      <div class=\"sub-seq-last-alarm\" id=\"onePPurgeLastAlarm\"></div>\n      <div class=\"purge-count-panel\" id=\"onePPurgeIdleCycleInfo\" style=\"display:none;\">\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">설정 횟수 :</span>\n          <span class=\"purge-count-box\">[ <span id=\"onePPurgeIdleCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">진행 횟수 :</span>\n          <span class=\"purge-count-box\">[ <span id=\"onePPurgeIdleCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"onePPurgeExecuteBtn\" style=\"margin:0;\">실행</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPurgeIdleCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPurgeIdleTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPurgeIdleExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPurgeIdleExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"onePPurgeIdleExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n\n    <div id=\"onePPurgePanel\" style=\"display:none;\">\n      <div class=\"sub-seq-step-label\" id=\"onePPurgeStepLabel\">Main 1 - Sub 1</div>\n      <div class=\"sub-seq-operation\" id=\"onePPurgeOperation\">-</div>\n      <div class=\"sub-seq-message\" id=\"onePPurgeMessage\">-</div>\n      <div class=\"sub-seq-valve-diff\" id=\"onePPurgeValveDiff\"></div>\n      <div class=\"sub-seq-timer\" id=\"onePPurgeTimer\">-</div>\n      <div class=\"sub-seq-acc-time\" id=\"onePPurgeAccTime\">누적 경과시간: 0초</div>\n      <div class=\"sub-seq-alarm-banner\" id=\"onePPurgeAlarmBanner\" style=\"display:none;\">\n        <div class=\"sub-seq-last-alarm\" id=\"onePPurgePanelAlarmMsg\"></div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"purge-count-panel\" id=\"onePPurgeCycleInfo\" style=\"display:none;\">\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">설정 횟수 :</span>\n            <span class=\"purge-count-box\">[ <span id=\"onePPurgeCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">진행 횟수 :</span>\n            <span class=\"purge-count-box\">[ <span id=\"onePPurgeCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n        </div>\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"onePPurgeAckBtn\" style=\"margin:0; display:none;\">확인</button>\n          <!-- 평소엔 \"취소\", 알람 배너가 떠 있는 동안엔 \"실행\"으로 바뀌어 재시작을 담당한다. -->\n          <!-- 테스트용 - 카운트다운/누적시간을 그 자리에서 멈추고 남은 시간부터 이어서\n               재개할 수 있다(사용자 요청). -->\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPurgePauseBtn\" style=\"margin:0;\">일시정지</button>\n          <!-- 테스트 기간 전용 - Step 1부터 즉시 다시 시작한다(사용자 요청). -->\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPurgeResetBtn\" style=\"margin:0;\">초기화</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPurgeCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPurgeTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <!-- 이 구간(2차측 Purge)에 연결된 서브시퀀스(OneP2_v1)를 엑셀로 내보내서 편집하고,\n             편집한 파일을 다시 불러와 그대로 반영한다(gms-sub-sequence-runner.js). -->\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPurgeExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPurgeExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"onePPurgeExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","1P_Pumping_자동진행.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>1P Pumping 자동진행 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 1P 구간 - Pumping\" 화면 분리 파일 - Status \"1P\" 4개\n     서브시퀀스(1-2차측 Vent Mode → 2차측 Purge → Pumping → 1차측 Purge) 중 3번째. 2차측\n     Purge(ns='onePPurge') 완료 직후 자동으로 시작된다(Operation.js의\n     showProgressCylExchangePurgeStep 특수 분기). 서브시퀀스 엑셀 엔진(gms-sub-sequence-runner.js,\n     ns='onePPumping')으로 실행 - 실제 내용은 data/gmsSubSequences/OneP3_v1.json. Step 7이\n     실제 Pumping 대기 구간으로, CONFIG \"PUMPING 시간[분]\"만큼 1분 단위로 카운트하며\n     HPT_{side} 초기값(최초 도달 시 1회 캡처)/현재값(실시간)을 함께 보여준다. 완료 시\n     자동으로 1차측 Purge(onePPrimaryPurge)로 넘어간다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressOnePPumpingAutoRunBody\">\n    <div class=\"step-badges-lg\">\n      <span class=\"step-badge-lg blinking\">1P</span>\n      <span class=\"step-badge-lg\">-L</span>\n      <span class=\"step-badge-lg\" data-vt-badge>-VT</span>\n      <span class=\"step-badge-lg\">2P</span>\n    </div>\n\n    <div id=\"onePPumpingIdle\">\n      <div class=\"progress-menu-desc\">Pumping 구간을 준비하는 중입니다...</div>\n      <div class=\"sub-seq-last-alarm\" id=\"onePPumpingLastAlarm\"></div>\n      <div class=\"purge-count-panel\" id=\"onePPumpingIdleCycleInfo\" style=\"display:none;\">\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">설정시간(분) :</span>\n          <span class=\"purge-count-box\">[ <span id=\"onePPumpingIdleCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">진행시간(분) :</span>\n          <span class=\"purge-count-box\">[ <span id=\"onePPumpingIdleCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"onePPumpingExecuteBtn\" style=\"margin:0;\">실행</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPumpingIdleCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPumpingIdleTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPumpingIdleExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPumpingIdleExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"onePPumpingIdleExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n\n    <div id=\"onePPumpingPanel\" style=\"display:none;\">\n      <div class=\"sub-seq-step-label\" id=\"onePPumpingStepLabel\">Main 1 - Sub 1</div>\n      <div class=\"sub-seq-operation\" id=\"onePPumpingOperation\">-</div>\n      <div class=\"sub-seq-message\" id=\"onePPumpingMessage\">-</div>\n      <div class=\"sub-seq-valve-diff\" id=\"onePPumpingValveDiff\"></div>\n      <div class=\"sub-seq-timer\" id=\"onePPumpingTimer\">-</div>\n      <div class=\"sub-seq-acc-time\" id=\"onePPumpingAccTime\">누적 경과시간: 0초</div>\n      <div class=\"sub-seq-alarm-banner\" id=\"onePPumpingAlarmBanner\" style=\"display:none;\">\n        <div class=\"sub-seq-last-alarm\" id=\"onePPumpingPanelAlarmMsg\"></div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <!-- 초기값/현재값(HPT_{side})은 Step 7(Pumping 대기)에 최초 도달했을 때부터 표시된다\n             (사용자 요청 - \"초기값,현재값,설정시간,진행시간 4개 값을 표현\"). 설정/진행시간은\n             기존 설정/진행 횟수 표시 메커니즘을 그대로 재사용하되(분 단위로 라벨만 변경),\n             초기값/현재값은 gms-sub-sequence-runner.js의 subSeqApplyCapture/\n             subSeqRefreshLiveCaptures가 채운다. -->\n        <div class=\"purge-count-panel\" id=\"onePPumpingCycleInfo\" style=\"display:none;\">\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">초기값(HPT) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"onePPumpingCaptureInitial\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">현재값(HPT) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"onePPumpingCaptureCurrent\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">설정시간(분) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"onePPumpingCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">진행시간(분) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"onePPumpingCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n        </div>\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"onePPumpingAckBtn\" style=\"margin:0; display:none;\">확인</button>\n          <!-- 평소엔 \"취소\", 알람 배너가 떠 있는 동안엔 \"실행\"으로 바뀌어 재시작을 담당한다. -->\n          <!-- 테스트용 - 카운트다운/누적시간을 그 자리에서 멈추고 남은 시간부터 이어서\n               재개할 수 있다(사용자 요청). -->\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPumpingPauseBtn\" style=\"margin:0;\">일시정지</button>\n          <!-- 테스트 기간 전용 - Step 1부터 즉시 다시 시작한다(사용자 요청). -->\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPumpingResetBtn\" style=\"margin:0;\">초기화</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPumpingCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPumpingTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <!-- 이 구간(Pumping)에 연결된 서브시퀀스(OneP3_v1)를 엑셀로 내보내서 편집하고,\n             편집한 파일을 다시 불러와 그대로 반영한다(gms-sub-sequence-runner.js). -->\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPumpingExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPumpingExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"onePPumpingExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","1P_자동진행.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>1P 1-2차측 Vent Mode 자동진행 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 1P 구간 - 1-2차측 Vent Mode\" 화면 분리 파일 - Status \"1P\"\n     4개 서브시퀀스(1-2차측 Vent Mode → 2차측 Purge → Pumping → 1차측 Purge) 중 1번째.\n     Puls 구간(ns='puls') 완료 직후 자동으로 시작된다(Operation.js의\n     showProgressCylExchangePurgeStep 특수 분기). 서브시퀀스 엑셀 엔진(gms-sub-sequence-runner.js,\n     ns='oneP')으로 실행 - 실제 내용은 data/gmsSubSequences/OneP_v1.json. 이 구간 동안은\n     큰 배지 \"1P\"가 점멸한다. 완료 시 자동으로 2차측 Purge(onePPurge)로 넘어가고, 나머지\n     3개(2차측 Purge → Pumping → 1차측 Purge)까지 전부 끝나야 Status가 -L(감압시험)로\n     넘어간다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressOnePAutoRunBody\">\n    <div class=\"step-badges-lg\">\n      <span class=\"step-badge-lg blinking\">1P</span>\n      <span class=\"step-badge-lg\">-L</span>\n      <span class=\"step-badge-lg\" data-vt-badge>-VT</span>\n      <span class=\"step-badge-lg\">2P</span>\n    </div>\n\n    <div id=\"onePIdle\">\n      <div class=\"progress-menu-desc\">1P 구간을 준비하는 중입니다...</div>\n      <div class=\"sub-seq-last-alarm\" id=\"onePLastAlarm\"></div>\n      <div class=\"purge-count-panel\" id=\"onePIdleCycleInfo\" style=\"display:none;\">\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">설정 횟수 :</span>\n          <span class=\"purge-count-box\">[ <span id=\"onePIdleCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">진행 횟수 :</span>\n          <span class=\"purge-count-box\">[ <span id=\"onePIdleCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"onePExecuteBtn\" style=\"margin:0;\">실행</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePIdleCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePIdleTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePIdleExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePIdleExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"onePIdleExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n\n    <div id=\"onePPanel\" style=\"display:none;\">\n      <div class=\"sub-seq-step-label\" id=\"onePStepLabel\">Main 1 - Sub 1</div>\n      <div class=\"sub-seq-operation\" id=\"onePOperation\">-</div>\n      <div class=\"sub-seq-message\" id=\"onePMessage\">-</div>\n      <div class=\"sub-seq-valve-diff\" id=\"onePValveDiff\"></div>\n      <div class=\"sub-seq-timer\" id=\"onePTimer\">-</div>\n      <div class=\"sub-seq-acc-time\" id=\"onePAccTime\">누적 경과시간: 0초</div>\n      <div class=\"sub-seq-alarm-banner\" id=\"onePAlarmBanner\" style=\"display:none;\">\n        <div class=\"sub-seq-last-alarm\" id=\"onePPanelAlarmMsg\"></div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"purge-count-panel\" id=\"onePCycleInfo\" style=\"display:none;\">\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">설정 횟수 :</span>\n            <span class=\"purge-count-box\">[ <span id=\"onePCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">진행 횟수 :</span>\n            <span class=\"purge-count-box\">[ <span id=\"onePCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n        </div>\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"onePAckBtn\" style=\"margin:0; display:none;\">확인</button>\n          <!-- 평소엔 \"취소\", 알람 배너가 떠 있는 동안엔 \"실행\"으로 바뀌어 재시작을 담당한다. -->\n          <!-- 테스트용 - 카운트다운/누적시간을 그 자리에서 멈추고 남은 시간부터 이어서\n               재개할 수 있다(사용자 요청). -->\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePPauseBtn\" style=\"margin:0;\">일시정지</button>\n          <!-- 테스트 기간 전용 - Step 1부터 즉시 다시 시작한다(사용자 요청). -->\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePResetBtn\" style=\"margin:0;\">초기화</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <!-- 이 구간(1P)에 연결된 서브시퀀스(OneP_v1)를 엑셀로 내보내서 편집하고, 편집한\n             파일을 다시 불러와 그대로 반영한다(gms-sub-sequence-runner.js). -->\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"onePExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"onePExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","HP&LP_Pump.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n  <meta charset=\"UTF-8\">\n  <title>HP&LP Pump 자동진행 - GMS 조작화면</title>\n  <link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressHpLpPumpBody\">\n    <div class=\"step-badges-lg\">\n      <span class=\"step-badge-lg blinking\">HP&LP Pump</span>\n    </div>\n\n    <div id=\"hpLpPumpIdle\">\n      <div class=\"progress-menu-desc\">HP&LP Pump 구간을 준비하는 중입니다...</div>\n      <div class=\"sub-seq-last-alarm\" id=\"hpLpPumpLastAlarm\"></div>\n      <div class=\"purge-count-panel\" id=\"hpLpPumpIdleCycleInfo\" style=\"display:none;\">\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">설정시간(분) :</span>\n          <span class=\"purge-count-box\">[ <span id=\"hpLpPumpIdleCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">진행시간(분) :</span>\n          <span class=\"purge-count-box\">[ <span id=\"hpLpPumpIdleCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"hpLpPumpExecuteBtn\" style=\"margin:0;\">실행</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"hpLpPumpIdleCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"hpLpPumpIdleTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"hpLpPumpIdleExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"hpLpPumpIdleExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"hpLpPumpIdleExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n\n    <div id=\"hpLpPumpPanel\" style=\"display:none;\">\n      <div class=\"sub-seq-step-label\" id=\"hpLpPumpStepLabel\">Main 15 - Sub 1</div>\n      <div class=\"sub-seq-operation\" id=\"hpLpPumpOperation\">-</div>\n      <div class=\"sub-seq-message\" id=\"hpLpPumpMessage\">-</div>\n      <div class=\"sub-seq-valve-diff\" id=\"hpLpPumpValveDiff\"></div>\n      <div class=\"sub-seq-timer\" id=\"hpLpPumpTimer\">-</div>\n      <div class=\"sub-seq-acc-time\" id=\"hpLpPumpAccTime\">누적 경과시간: 0초</div>\n      <div class=\"sub-seq-alarm-banner\" id=\"hpLpPumpAlarmBanner\" style=\"display:none;\">\n        <div class=\"sub-seq-last-alarm\" id=\"hpLpPumpPanelAlarmMsg\"></div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"purge-count-panel\" id=\"hpLpPumpCycleInfo\" style=\"display:none;\">\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">초기값(HPT) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"hpLpPumpCaptureInitial\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">현재값(HPT) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"hpLpPumpCaptureCurrent\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">설정시간(분) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"hpLpPumpCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">진행시간(분) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"hpLpPumpCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n        </div>\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"hpLpPumpAckBtn\" style=\"margin:0; display:none;\">확인</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"hpLpPumpPauseBtn\" style=\"margin:0;\">일시정지</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"hpLpPumpResetBtn\" style=\"margin:0;\">초기화</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"hpLpPumpCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"hpLpPumpTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"hpLpPumpExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"hpLpPumpExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"hpLpPumpExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","Maintenance Purge.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Maintenance Purge - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] Maintenance Purge\" 화면 분리 파일 - 유지보수 메뉴의\n     \"Maintenance Purge\" 버튼으로 들어온다. 스타일은 ../gms.css를 그대로 참조(복사 아님).\n     gms.js가 fetch해서 id=\"progressMaintenancePurgeBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <!-- 배관 청소 / 누출 시험 두 항목 - 실제 시퀀스 로직은 아직 없음(뼈대, \"준비 중\" 토스트).\n       취소는 유지보수 메뉴로 되돌아간다. -->\n  <div class=\"progress-menu-body\" id=\"progressMaintenancePurgeBody\">\n    <div class=\"progress-menu-desc\">진행할 메뉴를<br>선택 하십시오.</div>\n    <div class=\"progress-btn-group\">\n      <button type=\"button\" class=\"progress-btn\" data-purge-action=\"배관 청소\">배관 청소</button>\n      <button type=\"button\" class=\"progress-btn\" data-purge-action=\"누출 시험\">누출 시험</button>\n      <button type=\"button\" class=\"progress-aux-btn\" id=\"maintenancePurgeCancelBtn\">취소</button>\n    </div>\n  </div>\n</body>\n</html>\n","OPTION DISPLAY.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>OPTION DISPLAY - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"OPTION DISPLAY\" 화면 분리 파일. 보조 메뉴의 \"OPTION DISPLAY\" 버튼으로\n     들어온다(Operation.js의 auxMenuOptionDisplayBtn/showProgressOptionDisplay). CONFIG↔OPTION\n     탭의 OPTION 탭(gms.js renderOptionTable)에 있는 모든 옵션 값을 읽기 전용으로 한 번에\n     보여준다 - 변경 권한 없음(버튼/입력 없음, 전부 텍스트). 작업이력 화면과 같은 패턴으로\n     이 화면만 배관도를 숨기고 전체 폭을 쓴다(Operation.js의 setWorkLogFullWidth 참고 -\n     'optionDisplay'도 같은 대상에 포함됨). 실제 값 채우기는 public/gms-option-display.js가\n     담당한다(gms.js/Operation.js가 이미 들고 있는 전역 상태(PASSWORD_GATE_DEFS,\n     passwordGateOptions, manualStateHoldOption, vtUseOption, gcTypeOption, mainSequenceOrder,\n     mainSequenceEnabledTypes)를 그대로 읽어서 그린다 - 옵션 값의 출처가 두 군데로 갈라지면\n     안 되므로 별도 데이터를 새로 만들지 않는다). 스타일은 ../gms.css를 그대로 참조. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressOptionDisplayBody\">\n    <div class=\"progress-menu-desc\">OPTION 탭에서 설정된 값을 읽기 전용으로 보여줍니다(여기서는 변경할 수 없습니다).</div>\n    <div style=\"display:flex; gap:8px; margin-bottom:8px; flex-wrap:wrap;\">\n      <button type=\"button\" id=\"optionDisplayRefreshBtn\">🔄 새로고침</button>\n      <button type=\"button\" id=\"optionDisplayCloseBtn\" style=\"margin-left:auto;\">✕ 닫기</button>\n    </div>\n    <div class=\"option-display-columns\">\n      <div class=\"option-display-col\">\n        <div class=\"grid-table-title\">기본 옵션</div>\n        <table class=\"grid-table\">\n          <thead><tr><th>Item</th><th>Status</th></tr></thead>\n          <tbody id=\"optionDisplayBasicBody\"></tbody>\n        </table>\n        <div class=\"grid-table-title\" style=\"margin-top:16px;\">Main 시퀀스 순서(CYLINDER STEP STATUS)</div>\n        <div id=\"optionDisplayMainSequenceChips\" class=\"option-display-chip-row\"></div>\n      </div>\n      <div class=\"option-display-col\">\n        <div class=\"grid-table-title\">PASSWORD 게이트별 적용 여부</div>\n        <table class=\"grid-table\">\n          <thead><tr><th>Item</th><th>Status</th></tr></thead>\n          <tbody id=\"optionDisplayGateBody\"></tbody>\n        </table>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","PASSWORD.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>PASSWORD - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"PASSWORD\" 입력 화면 분리 파일. 스타일은 ../gms.css를 그대로\n     참조(복사 아님). gms.js가 fetch해서 id=\"progressPasswordBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <!-- \"유지 보수\" 클릭 시 나타나는 비밀번호 입력 화면 - 메뉴얼 흐름\n       [메인 메뉴] → [Password 입력] → [유지보수 메뉴] 중 두 번째 단계.\n       실제 검증 로직은 아직 없음(뼈대) - 자릿수 입력/지우기/취소만 실제로 동작한다.\n       passwordContextLabel: \"지금 어떤 상황에서 PASSWORD를 요구하는지\"를 안내 문구 바로\n       위에 보여준다(예: \"[A] 유지보수\" / \"[A] 수동 밸브 조작 취소\") - Operation.js의\n       showProgressPassword()가 매번 채워 넣는다. -->\n  <div class=\"progress-menu-body\" id=\"progressPasswordBody\">\n    <div class=\"progress-menu-desc password-context-label\" id=\"passwordContextLabel\"></div>\n    <div class=\"progress-menu-desc\">비밀번호를 입력하십시오.</div>\n    <!-- 키패드+확인/취소 묶음도 프레임 맨 아래에 붙는다(공통 규칙). -->\n    <div class=\"progress-btn-group\">\n      <div class=\"password-display\" id=\"passwordDisplay\"><span class=\"placeholder\">PASSWORD</span></div>\n      <div class=\"password-keypad\">\n        <button type=\"button\" class=\"keypad-btn\" data-digit=\"1\">1</button>\n        <button type=\"button\" class=\"keypad-btn\" data-digit=\"2\">2</button>\n        <button type=\"button\" class=\"keypad-btn\" data-digit=\"3\">3</button>\n        <button type=\"button\" class=\"keypad-btn\" data-digit=\"4\">4</button>\n        <button type=\"button\" class=\"keypad-btn\" data-digit=\"5\">5</button>\n        <button type=\"button\" class=\"keypad-btn\" data-digit=\"6\">6</button>\n        <button type=\"button\" class=\"keypad-btn\" data-digit=\"7\">7</button>\n        <button type=\"button\" class=\"keypad-btn\" data-digit=\"8\">8</button>\n        <button type=\"button\" class=\"keypad-btn\" data-digit=\"9\">9</button>\n        <button type=\"button\" class=\"keypad-btn keypad-aux\" id=\"passwordClearBtn\">CLR</button>\n        <button type=\"button\" class=\"keypad-btn\" data-digit=\"0\">0</button>\n        <button type=\"button\" class=\"keypad-btn keypad-aux\" id=\"passwordBackBtn\">⌫</button>\n      </div>\n      <div style=\"display:flex;gap:10px;margin-top:14px;\">\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"passwordCancelBtn\" style=\"flex:1;\">취소</button>\n        <button type=\"button\" class=\"progress-btn\" id=\"passwordConfirmBtn\" style=\"flex:1;margin-bottom:0;\">확인</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","PC_퍼지완료.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>퍼지완료 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 가스 공급\" 화면 분리 파일 - 4차 배관청소 \"실행\" → PASSWORD\n     통과 후 들어오는 \"교환후\" 자동 진행의 마지막 화면(Status \"4P\"→\"PC\", 퍼지 완료). 실린더\n     교환이 끝났으니 다음 메뉴(가스공급/B 선택/유지 보수/TREND)를 고르는 메인 메뉴와 같은\n     구성으로 보여준다(참고 사진 기준 - 메인 메뉴와 달리 첫 버튼이 \"실린더 교환\"이 아니라\n     \"가스공급\"). \"가스공급\"/\"B\" 선택은 아직 실제 로직 없음(뼈대, 토스트만) - \"유지 보수\"는\n     메인 메뉴와 동일하게 PASSWORD 게이트(mainMenu)를 거쳐 유지보수 메뉴로 간다. \"취소\"는\n     한 번 누르면 경고 토스트만 뜨고, 다시 한 번 눌러야 실제로 Status를 IDLE(준비 전)로\n     되돌리고 메인 메뉴로 나간다(Operation.js의 exchangePurgeCompleteCancelBtn 참고 - 실수로\n     한 번 누른 것만으로 전체 시퀀스가 초기화되지 않도록 하는 2단 확인). 스타일은\n     ../gms.css를 그대로 참조(복사 아님). gms.js가 fetch해서\n     id=\"progressExchangePurgeCompleteBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressExchangePurgeCompleteBody\">\n    <div class=\"progress-menu-desc\">진행할 메뉴를 선택 하십시오!</div>\n    <div class=\"progress-btn-group\">\n      <button type=\"button\" class=\"progress-btn\" id=\"exchangePurgeCompleteGasSupplyBtn\">가스공급</button>\n      <button type=\"button\" class=\"progress-btn\" id=\"exchangePurgeCompleteSwitchSideBtn\">\"B\" 선택</button>\n      <button type=\"button\" class=\"progress-btn\" id=\"exchangePurgeCompleteMaintenanceBtn\">유지 보수</button>\n      <button type=\"button\" class=\"progress-btn\" id=\"exchangePurgeCompleteTrendBtn\">TREND</button>\n      <div style=\"display:flex;gap:10px;margin-top:14px;\">\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangePurgeCompleteAuxBtn\" style=\"flex:1;\">보조 메뉴</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangePurgeCompleteCancelBtn\" style=\"flex:1;\">취소</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","Puls_자동진행.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Puls 자동진행 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] Puls 구간\" 화면 분리 파일 - Status \"Puls\"(잔류가스 Check,\n     Pulse Vent 2단계)의 실제 화면. 실린더 잠금 check 화면의 IDLE 사전확인 7단계(ns='idleCheck')\n     완료 직후 자동으로 시작된다(Operation.js의 showProgressCylExchangePurgeStep 특수 분기).\n     서브시퀀스 엑셀 엔진(gms-sub-sequence-runner.js, ns='puls')으로 실행 - 실제 2단계 내용은\n     data/gmsSubSequences/Puls_v1.json. 사용자 확인(실사 HMI 참고 자료) 결과 1P 배지는\n     Puls 구간부터 이미 점멸한다(1P 큰 배지가 Puls/1P 두 Status에 걸쳐 공유됨) - CYLINDER\n     STEP STATUS 패널의 작은 배지에는 \"Puls\"가 별도로 표시된다. -->\n\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressPulsAutoRunBody\">\n    <div class=\"step-badges-lg\">\n      <span class=\"step-badge-lg blinking\">1P</span>\n      <span class=\"step-badge-lg\">-L</span>\n      <span class=\"step-badge-lg\" data-vt-badge>-VT</span>\n      <span class=\"step-badge-lg\">2P</span>\n    </div>\n\n    <div id=\"pulsRunIdle\">\n      <div class=\"progress-menu-desc\">Puls 구간을 준비하는 중입니다...</div>\n      <div class=\"sub-seq-last-alarm\" id=\"pulsRunLastAlarm\"></div>\n      <!-- 알람으로 초기화되면 여기 idle로 돌아오는데, 진행 횟수가 몇 회까지 갔었는지도\n           알람 메시지와 함께 그대로 보여야 한다(사용자 요청 - \"진행횟수 유지하고 알람\n           메시지만 띄우면 됩니다\"). subSeqHandleAlarm이 알람 발생 시점의 값을 그대로\n           복사해 넣는다(라이브 갱신 아님 - \"실행\"을 다시 눌러 새로 시작하기 전까지 고정). -->\n      <div class=\"purge-count-panel\" id=\"pulsRunIdleCycleInfo\" style=\"display:none;\">\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">설정 횟수 :</span>\n          <span class=\"purge-count-box\">[ <span id=\"pulsRunIdleCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">진행 횟수 :</span>\n          <span class=\"purge-count-box\">[ <span id=\"pulsRunIdleCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n      </div>\n      <!-- 버튼 배치를 조정모드 idle(실행/취소/압력조정 + 엑셀 내보내기/불러오기 2줄)과\n           통일한다(사용자 요청 - \"실행 key 하나만 있음, 첫번째 아래 버튼처럼 배치\"). -->\n      <div class=\"progress-btn-group\">\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"pulsRunExecuteBtn\" style=\"margin:0;\">실행</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"pulsRunIdleCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"pulsRunIdleTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"pulsRunIdleExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"pulsRunIdleExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"pulsRunIdleExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n\n    <div id=\"pulsRunPanel\" style=\"display:none;\">\n      <div class=\"sub-seq-step-label\" id=\"pulsRunStepLabel\">Main 1 - Sub 1</div>\n      <div class=\"sub-seq-operation\" id=\"pulsRunOperation\">-</div>\n      <div class=\"sub-seq-message\" id=\"pulsRunMessage\">-</div>\n      <div class=\"sub-seq-valve-diff\" id=\"pulsRunValveDiff\"></div>\n      <div class=\"sub-seq-timer\" id=\"pulsRunTimer\">-</div>\n      <div class=\"sub-seq-acc-time\" id=\"pulsRunAccTime\">누적 경과시간: 0초</div>\n      <!-- 알람 배너 - 알람이 나도 화면을 idle로 바꾸지 않고 지금 보던 패널(Step 정보)을\n           그대로 둔 채 이 배너(메시지만)만 추가로 띄운다(사용자 요청 - \"화면 변경없이 기존\n           화면에 알람 메세지만 추가로\"). 재진행은 별도 확인 버튼이 아니라 하단 \"취소\" 자리가\n           알람 중엔 \"실행\"으로 바뀌어 담당한다(사용자 요청 - \"확인 key를 삭제하시고, 하단\n           버튼에 취소를 실행으로 변경\"). -->\n      <div class=\"sub-seq-alarm-banner\" id=\"pulsRunAlarmBanner\" style=\"display:none;\">\n        <div class=\"sub-seq-last-alarm\" id=\"pulsRunPanelAlarmMsg\"></div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <!-- 설정/진행 횟수 - 다른 화면들의 뼈대(예: 교환전2P_2차 배관청소.html)와 같은\n             .purge-count-panel 박스 스타일로 통일한다(사용자 요청). .progress-btn-group\n             안(조작 버튼 바로 위)에 둬서 버튼과 함께 화면 맨 아래로 붙는다(사용자 요청 -\n             원래는 margin-top:auto인 버튼 그룹보다 위, 즉 콘텐츠 쪽에 남아 버튼과 떨어져\n             있었다). 값은 입력칸이 아니라 읽기전용 표시(설정 횟수는 CONFIG \"Puls vent\n             설정횟수\"에서, 진행 횟수는 실행 중 실시간으로 채워진다) - id는 기존과 동일해서\n             JS(subSeqRenderCycleStatus) 변경 없이 그대로 값이 들어간다. -->\n        <div class=\"purge-count-panel\" id=\"pulsRunCycleInfo\" style=\"display:none;\">\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">설정 횟수 :</span>\n            <span class=\"purge-count-box\">[ <span id=\"pulsRunCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">진행 횟수 :</span>\n            <span class=\"purge-count-box\">[ <span id=\"pulsRunCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n        </div>\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"pulsRunAckBtn\" style=\"margin:0; display:none;\">확인</button>\n          <!-- 평소엔 \"취소\"(진행 중 중단), 알람 배너가 떠 있는 동안엔 \"실행\"으로 바뀌어\n               서브시퀀스를 다시 시작한다(subSeqWireOnce의 stopBtn 핸들러가 subSeqAlarmActive[ns]로\n               분기). -->\n          <!-- 테스트용 - 카운트다운/누적시간을 그 자리에서 멈추고 남은 시간부터 이어서\n               재개할 수 있다(사용자 요청). -->\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"pulsRunPauseBtn\" style=\"margin:0;\">일시정지</button>\n          <!-- 테스트 기간 전용 - Step 1부터 즉시 다시 시작한다(사용자 요청). -->\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"pulsRunResetBtn\" style=\"margin:0;\">초기화</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"pulsRunCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"pulsRunTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <!-- 이 구간(Puls)에 연결된 서브시퀀스(Puls_v1)를 엑셀로 내보내서 편집하고, 편집한\n             파일을 다시 불러와 그대로 반영한다(gms-sub-sequence-runner.js). -->\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"pulsRunExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"pulsRunExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"pulsRunExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","TREND.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>TREND - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 TREND 화면 - 각 시퀀스 화면의 \"TREND\" 버튼(~10곳)이 전부 이 화면을\n     연다(Operation.js showGmsTrend()). 옆(monitoring.html) 트렌드 모니터링과 같은 느낌으로\n     구성하되, GMS는 태그가 고정(unit1.json의 pts 15개)이라 그 태그들을 체크박스로 켜고 끄는\n     간단한 목록으로 구성했다(범용 변수 관리자는 아님). 실제 차트는 배관도화면 자리에\n     캔버스/미니 카드 그리드로 그린다(gms.js drawGmsTrendChart 등) - 이 화면은 오른쪽 컨트롤만 담당.\n     \"이전화면\"을 누르면 TREND 열기 전 화면(배관도+조작화면)으로 정확히 되돌아간다.\n     별도 데이터 로그: src/gmsHistory.js의 pt_samples/pt_samples_1m 테이블\n     (/api/gms/history/pt-trend) - 메인 앱의 트렌드 로그(data/trendVariables.json)와는 분리.\n     스타일은 ../gms.css를 그대로 참조. gms.js가 fetch해서 id=\"progressTrendBody\" 컨테이너에\n     주입한다. 태그 체크리스트는 Univer 그리드(#gmsTrendGridContainer, gms-trend-widget.js)로\n     그린다 - 그 위젯 스크립트는 gms.html에 직접 로드되어 있고, gms.js가 openGmsTrend()에서\n     window.initGmsTrendGrid()를 호출해 마운트를 요청한다(이 fragment는 늦게 주입되므로). -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressTrendBody\">\n    <!-- 폴링주기/시작/일시정지/정지/기록 불러오기·내보내기 - monitoring.html의 실행 툴바와\n         동일한 개념(gms.js의 gmsTrendRunStatus). GMS는 PT 값이 항상 WS로 계속 들어오지만,\n         이 버튼들은 \"지금 화면에 기록/표시할지\"를 제어한다(서버쪽 로그는 이 상태와 무관하게\n         항상 계속 쌓인다 - src/gmsHistory.js). -->\n    <div class=\"trend-toolbar-row\">\n      <label>폴링주기 <input type=\"number\" id=\"trendPollIntervalInput\" value=\"1000\" min=\"200\" step=\"100\" style=\"width:60px;\" /> ms</label>\n      <button type=\"button\" class=\"trend-toolbar-btn primary\" id=\"trendRunStartBtn\">▶ 시작</button>\n      <button type=\"button\" class=\"trend-toolbar-btn\" id=\"trendRunPauseBtn\">⏸ 일시정지</button>\n      <button type=\"button\" class=\"trend-toolbar-btn\" id=\"trendRunStopBtn\">⏹ 정지</button>\n    </div>\n    <div class=\"trend-toolbar-row\">\n      <button type=\"button\" class=\"trend-toolbar-btn\" id=\"trendHistoryImportBtn\" title=\"이전에 저장한 기록(Excel)을 불러와 오프라인으로 봅니다\">📈 기록 불러오기</button>\n      <button type=\"button\" class=\"trend-toolbar-btn\" id=\"trendHistoryExportBtn\" title=\"현재 그려진 기록을 Excel로 저장합니다\">📤 기록 내보내기</button>\n      <button type=\"button\" class=\"trend-toolbar-btn\" id=\"trendModeIndividualBtn\" title=\"선택한 태그마다 작은 그래프로 따로 표시\">개별 트렌드</button>\n      <button type=\"button\" class=\"trend-toolbar-btn primary\" id=\"trendModeTotalBtn\" title=\"선택한 태그를 한 그래프에 겹쳐 표시\">Total 트렌드</button>\n      <input type=\"file\" id=\"trendHistoryImportFile\" accept=\".xlsx\" hidden />\n    </div>\n    <div class=\"trend-range-row\">\n      <button type=\"button\" class=\"trend-toolbar-btn\" id=\"trendAutoFitBtn\" title=\"Y축을 현재 데이터에 맞게 자동 조정\">Auto Fit</button>\n      <label>Y min <input type=\"number\" id=\"trendYMin\" value=\"0\" step=\"1\" /></label>\n      <label>Y max <input type=\"number\" id=\"trendYMax\" value=\"100\" step=\"1\" /></label>\n      <button type=\"button\" class=\"trend-toolbar-btn\" id=\"trendYSetBtn\">Y Set</button>\n      <label>구간(초) <input type=\"number\" id=\"trendRangeSec\" value=\"60\" min=\"10\" step=\"10\" /></label>\n      <button type=\"button\" class=\"trend-toolbar-btn\" id=\"trendXSetBtn\">X Set</button>\n    </div>\n    <div class=\"trend-range-row\">\n      <label>시작 <input type=\"datetime-local\" id=\"trendXMinInput\" step=\"1\" /></label>\n      <label>종료 <input type=\"datetime-local\" id=\"trendXMaxInput\" step=\"1\" /></label>\n      <button type=\"button\" class=\"trend-toolbar-btn\" id=\"trendXRangeSetBtn\">범위 설정</button>\n    </div>\n    <!-- 태그 선택 목록 - Univer 시트(선택/태그/태그설명/현재값 4열). gms.js populateGmsTrendTagList()가\n         window.initGmsTrendGrid()로 마운트+태그 채우기를 요청한다.\n         #gmsTrendGridContainer 자체 CSS(flex:1 1 0; min-height:0 - gms-trend-widget.css)가\n         이 flex 컬럼(#progressTrendBody)의 남은 세로 공간을 전부 차지하도록 만든다. -->\n    <div id=\"gmsTrendGridContainer\"></div>\n    <div class=\"progress-btn-group\">\n      <button type=\"button\" class=\"progress-btn\" id=\"trendBackBtn\">◀ 이전화면</button>\n    </div>\n  </div>\n</body>\n</html>\n","가스공급_Cylinder Open.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Cylinder Open - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 자동 진행\" 화면 분리 파일 - 가스공급 자동 진행 네 번째\n     화면(Regulator Close 다음). 참고 사진 기준 위쪽 두 분면이 열림(초록), 아래 두 분면은\n     닫힘(검정) - .valve-turn-icon(../gms.css) 참고. 실제 로직은 아직 없음(뼈대) - \"확인\"은\n     다음 화면(Regulator 조정)으로, \"취소\"는 가스공급 진입 지점(PC/가스공급 화면)으로\n     되돌아간다. 스타일은 ../gms.css를 그대로 참조(복사 아님). gms.js가 fetch해서\n     id=\"progressGasSupplyCylinderOpenBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressGasSupplyCylinderOpenBody\">\n    <div class=\"valve-turn-icon\">\n      <div class=\"valve-turn-blade tl open\"></div>\n      <div class=\"valve-turn-blade tr open\"></div>\n      <div class=\"valve-turn-blade bl\"></div>\n      <div class=\"valve-turn-blade br\"></div>\n      <div class=\"valve-turn-label\">확 인</div>\n    </div>\n    <div class=\"progress-menu-desc\">실린더를 Open해<br>주십시오!</div>\n    <div class=\"progress-btn-group\">\n      <div style=\"display:flex;gap:10px;\">\n        <button type=\"button\" class=\"progress-btn\" id=\"gasSupplyCylinderOpenConfirmBtn\" style=\"flex:1;margin-bottom:0;\">확인</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"gasSupplyCylinderOpenCancelBtn\" style=\"flex:1;margin-top:0;\">취소</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","가스공급_FPV Open 확인.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>FPV Open 확인 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 가스공급 진행\" 화면 - 가스공급 자동 진행 여섯 번째\n     화면 (Step 6: FPV Open 확인). 공정 메인 공급 밸브(PMV / FPV) 개방 상태 확인.\n     \"확인\"을 누르면 Step 7 (가스공급 준비 완료) 화면으로 이동하고,\n     \"취소\"는 퍼지완료 이후 취소 비밀번호 게이트를 거쳐 PC(퍼지완료) 화면으로 복귀한다.\n     id=\"progressGasSupplyFpvOpenBody\" 컨테이너에 주입된다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressGasSupplyFpvOpenBody\">\n    <div class=\"valve-turn-icon\">\n      <div class=\"valve-turn-blade tl open\"></div>\n      <div class=\"valve-turn-blade tr open\"></div>\n      <div class=\"valve-turn-blade bl open\"></div>\n      <div class=\"valve-turn-blade br\"></div>\n      <div class=\"valve-turn-label\">확 인</div>\n    </div>\n    <div class=\"progress-menu-desc\">'FPV'을 열어주십시오!<br>확인을 Touch하면<br>공급준비가 완료됩니다.</div>\n    <div class=\"progress-btn-group\">\n      <div style=\"display:flex;gap:10px;\">\n        <button type=\"button\" class=\"progress-btn\" id=\"gasSupplyFpvOpenConfirmBtn\" style=\"flex:1;margin-bottom:0;\">확인</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"gasSupplyFpvOpenCancelBtn\" style=\"flex:1;margin-top:0;\">취소</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","가스공급_PMV Open 확인.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>PMV Open 확인 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 자동 진행\" 화면 분리 파일 - 가스공급 자동 진행 여섯 번째\n     화면(Regulator 조정 다음, PMV=AV14). 참고 사진 기준 세 분면이 열림(초록), 한 분면(우하)만\n     닫힘(검정) - .valve-turn-icon(../gms.css) 참고, 거의 다 열렸다는 뜻. \"확인\"을 누르면\n     실제로 가스가 공급된다는 안내 문구가 있다 - 실제 로직은 아직 없음(뼈대) - \"확인\"은\n     다음 화면(가스공급준비 완료)으로, \"취소\"는 가스공급 진입 지점(PC/가스공급 화면)으로\n     되돌아간다. 스타일은 ../gms.css를 그대로 참조(복사 아님). gms.js가 fetch해서\n     id=\"progressGasSupplyPmvOpenBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressGasSupplyPmvOpenBody\">\n    <div class=\"valve-turn-icon\">\n      <div class=\"valve-turn-blade tl open\"></div>\n      <div class=\"valve-turn-blade tr open\"></div>\n      <div class=\"valve-turn-blade bl open\"></div>\n      <div class=\"valve-turn-blade br\"></div>\n      <div class=\"valve-turn-label\">확 인</div>\n    </div>\n    <div class=\"progress-menu-desc\">'PMV'을 열어주십시오!<br>확인을 Touch하면<br>가스가 공급됩니다.</div>\n    <div class=\"progress-btn-group\">\n      <div style=\"display:flex;gap:10px;\">\n        <button type=\"button\" class=\"progress-btn\" id=\"gasSupplyPmvOpenConfirmBtn\" style=\"flex:1;margin-bottom:0;\">확인</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"gasSupplyPmvOpenCancelBtn\" style=\"flex:1;margin-top:0;\">취소</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","가스공급_Regulator Close.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Regulator Close - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 자동 진행\" 화면 분리 파일 - 가스공급 자동 진행 세 번째\n     화면(Valve shutter 장착 다음). 밸브를 돌리라는 안내는 참고 사진 속 4분면 팬휠 아이콘\n     (.valve-turn-icon, ../gms.css)으로 표시 - Regulator Close는 전부 잠그는 단계라 네\n     분면 모두 닫힘(검정)이다(다른 가스공급 밸브 안내 화면들은 열린 정도에 따라 초록\n     분면이 늘어난다). 실제 로직은 아직 없음(뼈대) - \"확인\"은 다음 화면(Cylinder open)으로,\n     \"취소\"는 가스공급 진입 지점(PC/가스공급 화면)으로 되돌아간다. 스타일은 ../gms.css를\n     그대로 참조(복사 아님). gms.js가 fetch해서 id=\"progressGasSupplyRegulatorCloseBody\"\n     컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressGasSupplyRegulatorCloseBody\">\n    <div class=\"valve-turn-icon\">\n      <div class=\"valve-turn-blade tl\"></div>\n      <div class=\"valve-turn-blade tr\"></div>\n      <div class=\"valve-turn-blade bl\"></div>\n      <div class=\"valve-turn-blade br\"></div>\n      <div class=\"valve-turn-label\">확 인</div>\n    </div>\n    <div class=\"progress-menu-desc\">Regulator를 잠궈주세요!</div>\n    <div class=\"progress-btn-group\">\n      <div style=\"display:flex;gap:10px;\">\n        <button type=\"button\" class=\"progress-btn\" id=\"gasSupplyRegulatorCloseConfirmBtn\" style=\"flex:1;margin-bottom:0;\">확인</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"gasSupplyRegulatorCloseCancelBtn\" style=\"flex:1;margin-top:0;\">취소</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","가스공급_Regulator 조정.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Regulator 조정 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 자동 진행\" 화면 분리 파일 - 가스공급 자동 진행 다섯 번째\n     화면(Cylinder open 다음). 참고 사진 기준 대각선 두 분면(좌상/우하)이 열림(초록), 나머지\n     두 분면은 닫힘(검정) - .valve-turn-icon(../gms.css) 참고. 실제 로직은 아직 없음(뼈대) -\n     \"확인\"은 다음 화면(PMV open 확인)으로, \"취소\"는 가스공급 진입 지점(PC/가스공급 화면)\n     으로 되돌아간다. 스타일은 ../gms.css를 그대로 참조(복사 아님). gms.js가 fetch해서\n     id=\"progressGasSupplyRegulatorAdjustBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressGasSupplyRegulatorAdjustBody\">\n    <div class=\"valve-turn-icon\">\n      <div class=\"valve-turn-blade tl open\"></div>\n      <div class=\"valve-turn-blade tr\"></div>\n      <div class=\"valve-turn-blade bl\"></div>\n      <div class=\"valve-turn-blade br open\"></div>\n      <div class=\"valve-turn-label\">확 인</div>\n    </div>\n    <div class=\"progress-menu-desc\">Regulator를<br>조정하여 주십시오!</div>\n    <div class=\"progress-btn-group\">\n      <div style=\"display:flex;gap:10px;\">\n        <button type=\"button\" class=\"progress-btn\" id=\"gasSupplyRegulatorAdjustConfirmBtn\" style=\"flex:1;margin-bottom:0;\">확인</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"gasSupplyRegulatorAdjustCancelBtn\" style=\"flex:1;margin-top:0;\">취소</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","가스공급_Valve shutter 장착.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Valve shutter 장착 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 자동 진행\" 화면 분리 파일 - 가스공급 자동 진행 두 번째\n     화면(공급 압력 확인 다음). 실제 로직은 아직 없음(뼈대) - \"확인\"은 다음 화면(Regulator\n     Close)으로, \"취소\"는 가스공급 진입 지점(PC/가스공급 화면)으로 되돌아간다. 스타일은\n     ../gms.css를 그대로 참조(복사 아님). gms.js가 fetch해서\n     id=\"progressGasSupplyValveShutterBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressGasSupplyValveShutterBody\">\n    <div class=\"barcode-check-title\">[ Valve shutter 장착 ]</div>\n    <div class=\"progress-menu-desc\" style=\"margin-top:20px;\">Gas Turn-On을 진행하고자 합니다.</div>\n    <div class=\"progress-menu-desc\">실린더에 Valve Shutter를 장착 하신 후<br>고정용 Bolt의 체결 상태를<br>확인하시기 바랍니다.</div>\n    <div class=\"progress-btn-group\">\n      <div style=\"display:flex;gap:10px;\">\n        <button type=\"button\" class=\"progress-btn\" id=\"gasSupplyValveShutterConfirmBtn\" style=\"flex:1;margin-bottom:0;\">확인</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"gasSupplyValveShutterCancelBtn\" style=\"flex:1;margin-top:0;\">취소</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","가스공급_공급중.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>가스공급 중 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 자동 진행\" 화면 분리 파일 - 가스공급준비 완료 화면의\n     \"확인\"(실제 가스공급 시작, Status \"READY\"→\"Service\") 다음에 들어오는 화면. 4색\n     팬휠 아이콘(.gas-flow-icon, ../gms.css)과 \"[측] Cylinder flow!\" 문구로 가스가 흐르고\n     있음을 나타낸다(측 표시는 Operation.js가 진입 시 갱신). 실제 유량/제어 로직은 아직\n     없음(뼈대) - \"일시정지\"/\"강제 교체\"/\"보조메뉴\"/TREND는 토스트만, \"공급중지\"는 공급을\n     끝내고 Status를 PC로 되돌린 뒤 PC/가스공급 화면으로 나간다, \"B\"/\"A\" 선택은 다른\n     화면들과 동일하게 반대 측의 실제 현재 Status 화면으로 전환한다(showScreenForSideStatus).\n     스타일은 ../gms.css를 그대로 참조(복사 아님). gms.js가 fetch해서\n     id=\"progressGasSupplyActiveBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressGasSupplyActiveBody\">\n    <div class=\"gas-flow-icon\">\n      <div class=\"gas-flow-blade tl\"></div>\n      <div class=\"gas-flow-blade tr\"></div>\n      <div class=\"gas-flow-blade bl\"></div>\n      <div class=\"gas-flow-blade br\"></div>\n    </div>\n    <div class=\"gas-flow-desc\" id=\"gasSupplyActiveFlowLabel\">A Cylinder flow!</div>\n    <div class=\"progress-btn-group\">\n      <div class=\"gas-flow-btn-grid\">\n        <button type=\"button\" class=\"progress-btn\" id=\"gasSupplyActivePauseBtn\">일시정지</button>\n        <button type=\"button\" class=\"progress-btn\" id=\"gasSupplyActiveStopBtn\">공급중지</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"gasSupplyActiveSwitchSideBtn\">\"B\" 선택</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"gasSupplyActiveForceChangeBtn\">강제 교체</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"gasSupplyActiveAuxBtn\">보조메뉴</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"gasSupplyActiveTrendBtn\">TREND</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","가스공급_동작재확인.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>가스공급 동작 재확인 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 자동 진행\" 화면 분리 파일 - 가스공급 중(Service) 화면의\n     \"일시정지\"/\"공급중지\"/\"강제 교체\" 버튼 → PASSWORD 통과 후 공통으로 들어오는 재확인\n     화면(세 버튼이 이 화면 하나를 공유하고, 안내 문구만 Operation.js가 동적으로 바꾼다 -\n     gasSupplyPendingAction/showGasSupplyConfirmAction 참고). \"실행\"을 눌러야 실제로\n     동작하고(\"일시정지\"는 PC/가스공급 화면으로, \"공급중지\"는 IDLE+메인 메뉴로, \"강제\n     교체\"는 이 측을 IDLE+메인 메뉴로 보낸 뒤 반대 측 가스공급 화면으로 전환), \"취소\"는\n     가스공급 중 화면으로 그냥 되돌아간다. 스타일은 ../gms.css를 그대로 참조(복사 아님).\n     gms.js가 fetch해서 id=\"progressGasSupplyConfirmActionBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressGasSupplyConfirmActionBody\">\n    <div class=\"progress-menu-desc\" id=\"gasSupplyConfirmActionDesc\">일시정지를 진행하시겠습니까?</div>\n    <div class=\"progress-btn-group\">\n      <div style=\"display:flex;gap:10px;\">\n        <button type=\"button\" class=\"progress-btn\" id=\"gasSupplyConfirmActionRunBtn\" style=\"flex:1;margin-bottom:0;\">실행</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"gasSupplyConfirmActionCancelBtn\" style=\"flex:1;margin-top:0;\">취소</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","가스공급_압력확인.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>공급전 압력및 Weight 확인 - GMS 조작화면</title>\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body gsp-pressure-check-body\" id=\"progressGasSupplyPressureCheckBody\">\n    <div class=\"barcode-check-title\" style=\"margin-bottom:6px;font-size:16px;\">[ 공급전 압력및 Weight 확인 ]</div>\n    <div class=\"progress-menu-desc\" style=\"font-size:13px;line-height:1.5;margin-bottom:14px;color:var(--text);\">\n      실린더 잠금 상태를 확인 하세요<br>\n      가스공급 전 1차/2차 배관 라인의 압력및 무게 상태 확인\n    </div>\n\n    <div class=\"gsp-readout-panel\" style=\"margin-top:auto;margin-bottom:12px;\">\n      <div class=\"gsp-readout-row\" id=\"gspHptRow\">\n        <span class=\"gsp-readout-label\" id=\"gspHptLabel\">HPT_A :</span>\n        <div class=\"gsp-readout-val-wrap\">\n          <span class=\"purge-count-box gsp-box\">[ <span class=\"purge-count-value\" id=\"gspHptVal\">--</span> ]</span>\n          <span class=\"gsp-readout-unit\">psi</span>\n        </div>\n      </div>\n      <div class=\"gsp-readout-row\" id=\"gspMptRow\">\n        <span class=\"gsp-readout-label\" id=\"gspMptLabel\">MPT_A :</span>\n        <div class=\"gsp-readout-val-wrap\">\n          <span class=\"purge-count-box gsp-box\">[ <span class=\"purge-count-value\" id=\"gspMptVal\">--</span> ]</span>\n          <span class=\"gsp-readout-unit\">psi</span>\n        </div>\n      </div>\n      <div class=\"gsp-readout-row\" id=\"gspLptRow\">\n        <span class=\"gsp-readout-label\" id=\"gspLptLabel\">LPT_A :</span>\n        <div class=\"gsp-readout-val-wrap\">\n          <span class=\"purge-count-box gsp-box\">[ <span class=\"purge-count-value\" id=\"gspLptVal\">--</span> ]</span>\n          <span class=\"gsp-readout-unit\">psi</span>\n        </div>\n      </div>\n      <div class=\"gsp-readout-row\" id=\"gspNptRow\">\n        <span class=\"gsp-readout-label\" id=\"gspNptLabel\">NPT_A :</span>\n        <div class=\"gsp-readout-val-wrap\">\n          <span class=\"purge-count-box gsp-box\">[ <span class=\"purge-count-value\" id=\"gspNptVal\">--</span> ]</span>\n          <span class=\"gsp-readout-unit\">psi</span>\n        </div>\n      </div>\n      <div class=\"gsp-readout-row\" id=\"gspWeightRow\">\n        <span class=\"gsp-readout-label\" id=\"gspWeightLabel\">WI_A :</span>\n        <div class=\"gsp-readout-val-wrap\">\n          <span class=\"purge-count-box gsp-box\">[ <span class=\"purge-count-value\" id=\"gspWeightVal\">0.00</span> ]</span>\n          <span class=\"gsp-readout-unit\">kg</span>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"progress-btn-group\" style=\"margin-top:0;\">\n      <div class=\"gas-btn-grid\">\n        <button type=\"button\" class=\"progress-btn\" id=\"gasSupplyPressureCheckRunBtn\">가스공급</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"gasSupplyPressureCheckAdjustModeBtn\">조정모드</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"gasSupplyPressureCheckLineVentBtn\">Line Vent</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"gasSupplyPressureCheckCancelBtn\">취소</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","가스공급_준비완료.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>가스공급준비 완료 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 가스공급 진행\" 화면 분리 파일 - 가스공급 자동 진행의 마지막\n     화면(Step 7: 가스공급준비 완료). 실시간 HPT, MPT, LPT, NPT, WI 계측값을 확인하고\n     \"확인\"을 누르면 Status가 Service(\"가스공급\")로 전환되며 실제 가스공급 화면으로 넘어간다.\n     \"취소\"는 퍼지완료 이후 취소 비밀번호 게이트를 거쳐 PC 화면으로 복귀한다.\n     id=\"progressGasSupplyReadyBody\" 컨테이너에 주입된다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body gsp-pressure-check-body\" id=\"progressGasSupplyReadyBody\">\n    <div class=\"barcode-check-title\" style=\"margin-bottom:6px;font-size:16px;\">[ 공급준비 완료 ]</div>\n    <div class=\"progress-menu-desc\" style=\"font-size:13px;line-height:1.5;margin-bottom:14px;color:var(--text);\">\n      공급준비가 완료되었습니다.<br>\n      실린더 압력및 무게값을 확인 하시기 바랍니다.<br>\n      확인을 누르면 가스공급 진행화면으로 전환 됩니다.\n    </div>\n\n    <div class=\"gsp-readout-panel\" style=\"margin-top:auto;margin-bottom:12px;\">\n      <div class=\"gsp-readout-row\" id=\"gspReadyHptRow\">\n        <span class=\"gsp-readout-label\" id=\"gspReadyHptLabel\">HPT_A :</span>\n        <div class=\"gsp-readout-val-wrap\">\n          <span class=\"purge-count-box gsp-box\">[ <span class=\"purge-count-value\" id=\"gspReadyHptVal\">--</span> ]</span>\n          <span class=\"gsp-readout-unit\">psi</span>\n        </div>\n      </div>\n      <div class=\"gsp-readout-row\" id=\"gspReadyMptRow\">\n        <span class=\"gsp-readout-label\" id=\"gspReadyMptLabel\">MPT_A :</span>\n        <div class=\"gsp-readout-val-wrap\">\n          <span class=\"purge-count-box gsp-box\">[ <span class=\"purge-count-value\" id=\"gspReadyMptVal\">--</span> ]</span>\n          <span class=\"gsp-readout-unit\">psi</span>\n        </div>\n      </div>\n      <div class=\"gsp-readout-row\" id=\"gspReadyLptRow\">\n        <span class=\"gsp-readout-label\" id=\"gspReadyLptLabel\">LPT_A :</span>\n        <div class=\"gsp-readout-val-wrap\">\n          <span class=\"purge-count-box gsp-box\">[ <span class=\"purge-count-value\" id=\"gspReadyLptVal\">--</span> ]</span>\n          <span class=\"gsp-readout-unit\">psi</span>\n        </div>\n      </div>\n      <div class=\"gsp-readout-row\" id=\"gspReadyNptRow\">\n        <span class=\"gsp-readout-label\" id=\"gspReadyNptLabel\">NPT_A :</span>\n        <div class=\"gsp-readout-val-wrap\">\n          <span class=\"purge-count-box gsp-box\">[ <span class=\"purge-count-value\" id=\"gspReadyNptVal\">--</span> ]</span>\n          <span class=\"gsp-readout-unit\">psi</span>\n        </div>\n      </div>\n      <div class=\"gsp-readout-row\" id=\"gspReadyWeightRow\">\n        <span class=\"gsp-readout-label\" id=\"gspReadyWeightLabel\">WI_A :</span>\n        <div class=\"gsp-readout-val-wrap\">\n          <span class=\"purge-count-box gsp-box\">[ <span class=\"purge-count-value\" id=\"gspReadyWeightVal\">0.00</span> ]</span>\n          <span class=\"gsp-readout-unit\">kg</span>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"progress-btn-group\" style=\"margin-top:0;\">\n      <div style=\"display:flex;gap:10px;\">\n        <button type=\"button\" class=\"progress-btn\" id=\"gasSupplyReadyConfirmBtn\" style=\"flex:1;margin-bottom:0;\">확인</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"gasSupplyReadyCancelBtn\" style=\"flex:1;margin-top:0;\">취소</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","교환전-L_감압시험.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>감압시험 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 교환전-L 감압시험\" 화면 분리 파일 - Status \"1P\" 완료 직후\n     자동으로 시작된다(Operation.js의 showProgressCylExchangePurgeStep 특수 분기). 서브시퀀스\n     엑셀 엔진(gms-sub-sequence-runner.js, ns='exchangePressureTest')으로 실행 - 1P\n     Pumping(OneP3_v1.json)과 완전히 같은 디자인/패턴(값 캡처 + 분 단위 진행시간 + 초 단위\n     실시간 표시)이다. 실제 내용은 data/gmsSubSequences/ExchL_v1.json(아직 뼈대, 밸브/조건\n     미정 - \"서브시퀀스 엑셀 내보내기\"로 받아 채운 뒤 \"불러오기\"로 반영). 완료 시\n     advanceToNextEnabledStatus로 다음 Status(VT 사용 옵션에 따라 -VT 또는 2P)로 넘어간다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressExchangePressureTestBody\">\n    <div class=\"step-badges-lg\">\n      <span class=\"step-badge-lg done\">1P</span>\n      <span class=\"step-badge-lg blinking\">-L</span>\n      <span class=\"step-badge-lg\" data-vt-badge>-VT</span>\n      <span class=\"step-badge-lg\">2P</span>\n    </div>\n\n    <div id=\"exchangePressureTestIdle\">\n      <div class=\"progress-menu-desc\">감압시험 구간을 준비하는 중입니다...</div>\n      <div class=\"sub-seq-last-alarm\" id=\"exchangePressureTestLastAlarm\"></div>\n      <div class=\"purge-count-panel\" id=\"exchangePressureTestIdleCycleInfo\" style=\"display:none;\">\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">설정시간(분) :</span>\n          <span class=\"purge-count-box\">[ <span id=\"exchangePressureTestIdleCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">진행시간(분) :</span>\n          <span class=\"purge-count-box\">[ <span id=\"exchangePressureTestIdleCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"exchangePressureTestExecuteBtn\" style=\"margin:0;\">실행</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangePressureTestIdleCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangePressureTestIdleTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangePressureTestIdleExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangePressureTestIdleExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"exchangePressureTestIdleExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n\n    <div id=\"exchangePressureTestPanel\" style=\"display:none;\">\n      <div class=\"sub-seq-step-label\" id=\"exchangePressureTestStepLabel\">Main 1 - Sub 1</div>\n      <div class=\"sub-seq-operation\" id=\"exchangePressureTestOperation\">-</div>\n      <div class=\"sub-seq-message\" id=\"exchangePressureTestMessage\">-</div>\n      <div class=\"sub-seq-valve-diff\" id=\"exchangePressureTestValveDiff\"></div>\n      <div class=\"sub-seq-timer\" id=\"exchangePressureTestTimer\">-</div>\n      <div class=\"sub-seq-acc-time\" id=\"exchangePressureTestAccTime\">누적 경과시간: 0초</div>\n      <div class=\"sub-seq-alarm-banner\" id=\"exchangePressureTestAlarmBanner\" style=\"display:none;\">\n        <div class=\"sub-seq-last-alarm\" id=\"exchangePressureTestPanelAlarmMsg\"></div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <!-- 초기값/현재값(HPT_{side})은 Step 2(감압시험 대기)에 최초 도달했을 때부터\n             표시된다(1P Pumping 화면과 동일한 구성). -->\n        <div class=\"purge-count-panel\" id=\"exchangePressureTestCycleInfo\" style=\"display:none;\">\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\" id=\"exchangePressureTestInitialLabel\">초기값(HPT) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangePressureTestCaptureInitial\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\" id=\"exchangePressureTestCurrentLabel\">현재값(HPT) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangePressureTestCaptureCurrent\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">압력변동기준 :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangePressureTestCaptureLimit\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">설정시간(분) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangePressureTestCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">진행시간(분) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangePressureTestCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n        </div>\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"exchangePressureTestAckBtn\" style=\"margin:0; display:none;\">확인</button>\n          <!-- 평소엔 \"취소\", 알람 배너가 떠 있는 동안엔 \"실행\"으로 바뀌어 재시작을 담당한다. -->\n          <!-- 테스트용 - 카운트다운/누적시간을 그 자리에서 멈추고 남은 시간부터 이어서\n               재개할 수 있다. -->\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangePressureTestPauseBtn\" style=\"margin:0;\">일시정지</button>\n          <!-- 테스트 기간 전용 - Step 1부터 즉시 다시 시작한다(사용자 요청). -->\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangePressureTestResetBtn\" style=\"margin:0;\">초기화</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangePressureTestCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangePressureTestTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <!-- 이 구간(-L 감압시험)에 연결된 서브시퀀스(ExchL_v1)를 엑셀로 내보내서 편집하고,\n             편집한 파일을 다시 불러와 그대로 반영한다(gms-sub-sequence-runner.js). -->\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangePressureTestExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangePressureTestExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"exchangePressureTestExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","교환전-VT_VT 감압시험.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>VT 감압시험 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 자동 진행\" 화면 분리 파일 - 교환전 실린더 교환 자동 진행\n     시퀀스 중 감압시험(-L) 완료 직후, VT 사용 옵션이 적용일 때만 들어오는 \"VT 감압 시험\"\n     화면(Status \"-VT\", 2차 배관청소(2P) 전 단계). 서브시퀀스 엑셀 엔진(gms-sub-sequence-runner.js,\n     ns='vtTest')으로 실행 - 실제 내용은 data/gmsSubSequences/VtTest_v1.json(사용자가 첨부한\n     실제 플로우차트 기준 3단계: ①VT Process Pumping(단순 시간대기) ②VT 1/2차측 Pumping+진공\n     상한 판정(실 알람) ③VT 점검/누출시험(초기값 캡처 후 :CAPOFFSET로 허용 변동폭 이내인지\n     실 알람 판정)). \"초기값/현재값\"은 3단계에서만 채워진다. \"설정 값\"은 지금 감시 중인\n     Step의 비교 기준(2단계엔 진공 상한, 3단계엔 초기값+누출허용범위)을 그대로 보여준다.\n     완료 시 자동으로 다음 Status(2P)로 넘어간다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressExchangeVtTestBody\">\n    <div class=\"step-badges-lg\">\n      <span class=\"step-badge-lg done\">1P</span>\n      <span class=\"step-badge-lg done\">-L</span>\n      <span class=\"step-badge-lg blinking\" data-vt-badge>-VT</span>\n      <span class=\"step-badge-lg\">2P</span>\n    </div>\n\n    <div id=\"exchangeVtTestIdle\">\n      <div class=\"progress-menu-desc\">VT 감압 시험 구간을 준비하는 중입니다...</div>\n      <div class=\"sub-seq-last-alarm\" id=\"exchangeVtTestLastAlarm\"></div>\n      <div class=\"purge-count-panel\" id=\"exchangeVtTestIdleCycleInfo\" style=\"display:none;\">\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">설정시간(분) :</span>\n          <span class=\"purge-count-box\">[ <span id=\"exchangeVtTestIdleCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">진행시간(분) :</span>\n          <span class=\"purge-count-box\">[ <span id=\"exchangeVtTestIdleCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"exchangeVtTestExecuteBtn\" style=\"margin:0;\">실행</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeVtTestIdleCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeVtTestIdleTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeVtTestIdleExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeVtTestIdleExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"exchangeVtTestIdleExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n\n    <div id=\"exchangeVtTestPanel\" style=\"display:none;\">\n      <div class=\"sub-seq-step-label\" id=\"exchangeVtTestStepLabel\">Main 1 - Sub 1</div>\n      <div class=\"sub-seq-operation\" id=\"exchangeVtTestOperation\">-</div>\n      <div class=\"sub-seq-message\" id=\"exchangeVtTestMessage\">-</div>\n      <div class=\"sub-seq-valve-diff\" id=\"exchangeVtTestValveDiff\"></div>\n      <div class=\"sub-seq-timer\" id=\"exchangeVtTestTimer\">-</div>\n      <div class=\"sub-seq-acc-time\" id=\"exchangeVtTestAccTime\">누적 경과시간: 0초</div>\n      <div class=\"sub-seq-alarm-banner\" id=\"exchangeVtTestAlarmBanner\" style=\"display:none;\">\n        <div class=\"sub-seq-last-alarm\" id=\"exchangeVtTestPanelAlarmMsg\"></div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"purge-count-panel\" id=\"exchangeVtTestCycleInfo\" style=\"display:none;\">\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">설정시간(분) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangeVtTestCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">진행시간(분) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangeVtTestCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n        </div>\n        <!-- 초기값/현재값(VT_{side})은 3단계(VT 점검/누출시험, Step 21)에 도달했을 때부터\n             표시된다. \"설정 값\"은 지금 감시 중인 Step의 비교 기준을 그대로 보여준다\n             (subSeqSetSettingValue - 2단계엔 진공 상한, 3단계엔 초기값+누출허용범위). -->\n        <div class=\"purge-count-panel value-panel\">\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">설정 값 :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangeVtTestSetValue\" class=\"purge-count-value\" style=\"min-width:44px;\">0.000</span> ] Torr</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">초기 값 :</span>\n            <span class=\"purge-count-box initial-value\">[ <span id=\"exchangeVtTestInitialValue\" class=\"purge-count-value\" style=\"min-width:44px;\">--</span> ] Torr</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">현재 값 :</span>\n            <span class=\"purge-count-box current-value\">[ <span id=\"exchangeVtTestCurrentValue\" class=\"purge-count-value\" style=\"min-width:44px;\">--</span> ] Torr</span>\n          </div>\n        </div>\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"exchangeVtTestAckBtn\" style=\"margin:0; display:none;\">확인</button>\n          <!-- 평소엔 \"취소\", 알람 배너가 떠 있는 동안엔 \"실행\"으로 바뀌어 재시작을 담당한다. -->\n          <!-- 테스트용 - 카운트다운/누적시간을 그 자리에서 멈추고 남은 시간부터 이어서\n               재개할 수 있다. -->\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeVtTestPauseBtn\" style=\"margin:0;\">일시정지</button>\n          <!-- 테스트 기간 전용 - Step 1부터 즉시 다시 시작한다(사용자 요청). -->\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeVtTestResetBtn\" style=\"margin:0;\">초기화</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeVtTestCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeVtTestTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <!-- 이 구간(VT 감압시험)에 연결된 서브시퀀스(VtTest_v1)를 엑셀로 내보내서 편집하고,\n             편집한 파일을 다시 불러와 그대로 반영한다(gms-sub-sequence-runner.js). -->\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeVtTestExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeVtTestExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"exchangeVtTestExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","교환전1P_실린더 잠금 check.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>실린더 잠금 check - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 실린더 잠금 check\" 화면 분리 파일 - 메인 메뉴의\n     \"실린더 교환\" → PASSWORD 확인 후 들어온다. 이 화면이 \"Puls\" 구간(실린더교환.xlsx\n     \"3차 수정본\" 시트 4~10번, 실린더 확인 → DATA 확인 → VALVE SHUTTER 확인 → 실린더\n     VALVE 확인 → 스티커 제거 → PUMP 확인 → 확인, 7단계)의 진입점이다 - 서브시퀀스 엑셀\n     엔진(gms-sub-sequence-runner.js, ns='puls')으로 실행되며, 실제 7단계 내용은\n     data/gmsSubSequences/Puls_v1.json. 이 7단계가 진행되는 동안은 아직 1P가 아니라서\n     .step-badges-lg 중 어느 것도 점멸하지 않는다(전부 1P 이전 단계) - 7단계를 모두\n     마쳐야(\"확인\") 비로소 Status가 1P로 넘어가며 1P 배지가 점멸을 시작한다\n     (Operation.js의 cylinderLockReturnBtn 핸들러, onFinish 콜백 참고).\n\n     idle(#cylinderLockIdle) 상태에서 \"실행\"을 누르면 Puls 서브시퀀스가 시작되고\n     #cylinderLockPanel로 전환된다(런너가 직접 토글, 압력 조정 모드.html와 동일 패턴).\n     서브시퀀스 엑셀 내보내기/불러오기 버튼도 idle 상태에 배치한다(조정모드와 동일 위치\n     관례). 스타일은 ../gms.css를 그대로 참조(복사 아님). gms.js가 fetch해서\n     id=\"progressCylinderLockCheckBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressCylinderLockCheckBody\">\n    <div class=\"step-badges-lg\">\n      <span class=\"step-badge-lg\">1P</span>\n      <span class=\"step-badge-lg\">-L</span>\n      <span class=\"step-badge-lg\" data-vt-badge>-VT</span>\n      <span class=\"step-badge-lg\">2P</span>\n    </div>\n\n    <div id=\"cylinderLockIdle\">\n      <div class=\"progress-menu-desc pt-test-warn\">실린더를 잠근 후<br>실행하십시오!</div>\n      <div class=\"progress-btn-group\">\n        <div class=\"purge-count-panel\">\n          <div class=\"purge-count-label\" style=\"text-align:center;margin-bottom:8px;\">[ Pumping ]</div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">설정 :</span>\n            <span class=\"purge-count-box\">[ <input type=\"number\" id=\"cylinderLockPumpingSet\" class=\"purge-count-input\" min=\"0\" max=\"100\" step=\"1\" value=\"0\" /> ]분</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">진행 :</span>\n            <span class=\"purge-count-box\">[ <span id=\"cylinderLockPumpingProgress\" class=\"purge-count-value\">100</span> ]분</span>\n          </div>\n        </div>\n        <div class=\"purge-count-panel value-panel\">\n          <div class=\"purge-count-label\" style=\"text-align:center;margin-bottom:8px;\">[ 퍼지 횟수 ]</div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">설정 :</span>\n            <span class=\"purge-count-box\">[ <input type=\"number\" id=\"cylinderLockPurgeSet\" class=\"purge-count-input\" min=\"0\" step=\"1\" value=\"0\" /> ]회</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">진행 :</span>\n            <span class=\"purge-count-box\">[ <span id=\"cylinderLockPurgeProgress\" class=\"purge-count-value\">0</span> ]회</span>\n          </div>\n        </div>\n        <div style=\"display:flex;gap:10px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"cylinderLockReturnBtn\" style=\"flex:1;margin-top:0;\">실행</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"cylinderLockCancelBtn\" style=\"flex:1;margin-top:0;\">취소</button>\n          <button type=\"button\" class=\"progress-btn\" id=\"cylinderLockTrendBtn\" style=\"flex:1;margin-bottom:0;\">TREND</button>\n        </div>\n        <!-- 이 구간(Puls)에 연결된 서브시퀀스(Puls_v1)를 엑셀로 내보내서 편집하고, 편집한\n             파일을 다시 불러와 그대로 반영한다(gms-sub-sequence-runner.js). -->\n        <div style=\"display:flex;gap:10px;margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"pulsExcelExportBtn\" style=\"flex:1;margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"pulsExcelImportBtn\" style=\"flex:1;margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"pulsExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n\n    <div id=\"cylinderLockPanel\" style=\"display:none;\">\n      <div class=\"sub-seq-step-label\" id=\"pulsStepLabel\">Main 1 - Sub 1</div>\n      <div class=\"sub-seq-operation\" id=\"pulsOperation\">-</div>\n      <div class=\"sub-seq-message\" id=\"pulsMessage\">-</div>\n      <div class=\"sub-seq-valve-diff\" id=\"pulsValveDiff\"></div>\n      <div class=\"sub-seq-timer\" id=\"pulsTimer\">-</div>\n      <div class=\"sub-seq-acc-time\" id=\"pulsAccTime\">누적 경과시간: 0초</div>\n      <div class=\"sub-seq-cycle-info\" id=\"pulsCycleInfo\" style=\"display:none;\">설정 횟수: <span id=\"pulsCycleTarget\">-</span>회 / 진행 횟수: <span id=\"pulsCycleCurrent\">-</span>회</div>\n      <div class=\"progress-btn-group\">\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"pulsAckBtn\" style=\"margin:0; display:none;\">확인</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"pulsCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"pulsTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","교환전2P_2차 배관청소.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>2차 배관청소 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 2차 배관청소\" 화면 분리 파일 - Status \"2P\". 감압시험(-L, 또는\n     VT 사용 옵션 적용 시 -VT) 완료 직후 자동으로 시작된다(Operation.js의\n     showProgressCylExchangePurgeStep 특수 분기). 서브시퀀스 엑셀 엔진(gms-sub-sequence-runner.js,\n     ns='twoP')으로 실행 - 실제 내용은 data/gmsSubSequences/TwoP_v1.json(배관진공 확인 → N2 Purge →\n     예약어 '진행횟수'로 CONFIG \"교환전 2차 퍼지진행 횟수\"만큼 반복, 1P 구간의 1차측\n     Purge(OneP4_v1)와 완전히 동일한 구조). 완료 시 PASSWORD(\"실린더 교체\") 확인 후 다음\n     Status(CC, 용기교체)로 넘어간다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressExchangeSecondPurgeBody\">\n    <div class=\"step-badges-lg\">\n      <span class=\"step-badge-lg done\">1P</span>\n      <span class=\"step-badge-lg done\">-L</span>\n      <span class=\"step-badge-lg done\" data-vt-badge>-VT</span>\n      <span class=\"step-badge-lg blinking\">2P</span>\n    </div>\n\n    <div id=\"exchangeSecondPurgeIdle\">\n      <div class=\"progress-menu-desc\">2차 배관청소 구간을 준비하는 중입니다...</div>\n      <div class=\"sub-seq-last-alarm\" id=\"exchangeSecondPurgeLastAlarm\"></div>\n      <div class=\"purge-count-panel\" id=\"exchangeSecondPurgeIdleCycleInfo\" style=\"display:none;\">\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">설정 횟수 :</span>\n          <span class=\"purge-count-box\">[ <span id=\"exchangeSecondPurgeIdleCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">진행 횟수 :</span>\n          <span class=\"purge-count-box\">[ <span id=\"exchangeSecondPurgeIdleCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"exchangeSecondPurgeExecuteBtn\" style=\"margin:0;\">실행</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeSecondPurgeIdleCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeSecondPurgeIdleTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeSecondPurgeIdleExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeSecondPurgeIdleExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"exchangeSecondPurgeIdleExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n\n    <div id=\"exchangeSecondPurgePanel\" style=\"display:none;\">\n      <div class=\"sub-seq-step-label\" id=\"exchangeSecondPurgeStepLabel\">Main 1 - Sub 1</div>\n      <div class=\"sub-seq-operation\" id=\"exchangeSecondPurgeOperation\">-</div>\n      <div class=\"sub-seq-message\" id=\"exchangeSecondPurgeMessage\">-</div>\n      <div class=\"sub-seq-valve-diff\" id=\"exchangeSecondPurgeValveDiff\"></div>\n      <div class=\"sub-seq-timer\" id=\"exchangeSecondPurgeTimer\">-</div>\n      <div class=\"sub-seq-acc-time\" id=\"exchangeSecondPurgeAccTime\">누적 경과시간: 0초</div>\n      <div class=\"sub-seq-alarm-banner\" id=\"exchangeSecondPurgeAlarmBanner\" style=\"display:none;\">\n        <div class=\"sub-seq-last-alarm\" id=\"exchangeSecondPurgePanelAlarmMsg\"></div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"purge-count-panel\" id=\"exchangeSecondPurgeCycleInfo\" style=\"display:none;\">\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">설정 횟수 :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangeSecondPurgeCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">진행 횟수 :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangeSecondPurgeCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n        </div>\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"exchangeSecondPurgeAckBtn\" style=\"margin:0; display:none;\">확인</button>\n          <!-- 평소엔 \"취소\", 알람 배너가 떠 있는 동안엔 \"실행\"으로 바뀌어 재시작을 담당한다. -->\n          <!-- 테스트용 - 카운트다운/누적시간을 그 자리에서 멈추고 남은 시간부터 이어서\n               재개할 수 있다(사용자 요청). -->\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeSecondPurgePauseBtn\" style=\"margin:0;\">일시정지</button>\n          <!-- 테스트 기간 전용 - Step 1부터 즉시 다시 시작한다(사용자 요청). -->\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeSecondPurgeResetBtn\" style=\"margin:0;\">초기화</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeSecondPurgeCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeSecondPurgeTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <!-- 이 구간(2차 배관청소)에 연결된 서브시퀀스(TwoP_v1)를 엑셀로 내보내서 편집하고,\n             편집한 파일을 다시 불러와 그대로 반영한다(gms-sub-sequence-runner.js). -->\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeSecondPurgeExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeSecondPurgeExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"exchangeSecondPurgeExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","교환후+L_가압시험.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>가압시험 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 교환후+L 가압시험\" 화면 분리 파일 - 3차 배관청소 다음,\n     \"교환후\" 자동 진행의 두 번째 화면(Status \"+L\" - 3P → +L → [VT 옵션] → 4P 순서). 서브시퀀스\n     엑셀 엔진(gms-sub-sequence-runner.js, ns='afterPlusL')으로 실행 - 교환전 -L\n     (exchangePressureTest)과 동일한 CAPTURE+분단위 반복판정 디자인(초기값/현재값 표시)이지만\n     안전조건 방향은 반대(가압 시험이라 압력이 하한 아래로 새면 알람). 실제 내용은\n     data/gmsSubSequences/AfterPlusL_v1.json(아직 뼈대, 밸브/조건 추정치 - \"서브시퀀스 엑셀\n     내보내기\"로 받아 채운 뒤 \"불러오기\"로 반영). 완료 시 advanceToNextEnabledStatus로 다음\n     Status(VT 사용 옵션에 따라 -VT 또는 4P)로 넘어간다. 스타일은 ../gms.css를 그대로\n     참조(복사 아님). gms.js가 fetch해서 id=\"progressExchangeAfterPressureTestBody\" 컨테이너에\n     주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressExchangeAfterPressureTestBody\">\n    <div class=\"step-badges-lg\">\n      <span class=\"step-badge-lg done\">3P</span>\n      <span class=\"step-badge-lg blinking\">+L</span>\n      <span class=\"step-badge-lg\" data-vt-badge>-VT</span>\n      <span class=\"step-badge-lg\">4P</span>\n      <span class=\"step-badge-lg\">PC</span>\n    </div>\n\n    <div id=\"exchangeAfterPressureTestIdle\">\n      <div class=\"progress-menu-desc\">가압시험 구간을 준비하는 중입니다...</div>\n      <div class=\"sub-seq-last-alarm\" id=\"exchangeAfterPressureTestLastAlarm\"></div>\n      <div class=\"purge-count-panel\" id=\"exchangeAfterPressureTestIdleCycleInfo\" style=\"display:none;\">\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">설정시간(분) :</span>\n          <span class=\"purge-count-box\">[ <span id=\"exchangeAfterPressureTestIdleCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">진행시간(분) :</span>\n          <span class=\"purge-count-box\">[ <span id=\"exchangeAfterPressureTestIdleCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"exchangeAfterPressureTestExecuteBtn\" style=\"margin:0;\">실행</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterPressureTestIdleCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterPressureTestIdleTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterPressureTestIdleExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterPressureTestIdleExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"exchangeAfterPressureTestIdleExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n\n    <div id=\"exchangeAfterPressureTestPanel\" style=\"display:none;\">\n      <div class=\"sub-seq-step-label\" id=\"exchangeAfterPressureTestStepLabel\">Main 1 - Sub 1</div>\n      <div class=\"sub-seq-operation\" id=\"exchangeAfterPressureTestOperation\">-</div>\n      <div class=\"sub-seq-message\" id=\"exchangeAfterPressureTestMessage\">-</div>\n      <div class=\"sub-seq-valve-diff\" id=\"exchangeAfterPressureTestValveDiff\"></div>\n      <div class=\"sub-seq-timer\" id=\"exchangeAfterPressureTestTimer\">-</div>\n      <div class=\"sub-seq-acc-time\" id=\"exchangeAfterPressureTestAccTime\">누적 경과시간: 0초</div>\n      <div class=\"sub-seq-alarm-banner\" id=\"exchangeAfterPressureTestAlarmBanner\" style=\"display:none;\">\n        <div class=\"sub-seq-last-alarm\" id=\"exchangeAfterPressureTestPanelAlarmMsg\"></div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <!-- 초기값/현재값(HPT_{side})은 안정화 대기 Step에 최초 도달했을 때부터 표시된다\n             (교환전 -L 감압시험 화면과 동일한 구성). -->\n        <div class=\"purge-count-panel\" id=\"exchangeAfterPressureTestCycleInfo\" style=\"display:none;\">\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\" id=\"exchangeAfterPressureTestInitialLabel\">초기값(HPT) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangeAfterPressureTestCaptureInitial\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\" id=\"exchangeAfterPressureTestCurrentLabel\">현재값(HPT) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangeAfterPressureTestCaptureCurrent\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">압력변동기준 :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangeAfterPressureTestCaptureLimit\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">설정시간(분) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangeAfterPressureTestCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">진행시간(분) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangeAfterPressureTestCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n        </div>\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"exchangeAfterPressureTestAckBtn\" style=\"margin:0; display:none;\">확인</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterPressureTestPauseBtn\" style=\"margin:0;\">일시정지</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterPressureTestResetBtn\" style=\"margin:0;\">초기화</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterPressureTestCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterPressureTestTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterPressureTestExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterPressureTestExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"exchangeAfterPressureTestExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","교환후-VT_VT감압시험.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>VT 감압시험 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 자동 진행\" 화면 분리 파일 - VT 사용 옵션이 적용일 때만\n     교환후 +L 가압시험 다음(Status \"-VT\" - 3P → +L → -VT → 4P 순서)에 들어오는 화면.\n     교환전-VT_VT 감압시험.html과 완전히 동일한 로직(같은 참고 플로우차트, 서브시퀀스 엑셀\n     엔진 ns='afterVtTest', data/gmsSubSequences/AfterVtTest_v1.json) - id만 전부 별도.\n     완료 시 자동으로 다음 Status(4P)로 넘어간다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressExchangeAfterVtTestBody\">\n    <div class=\"step-badges-lg\">\n      <span class=\"step-badge-lg done\">3P</span>\n      <span class=\"step-badge-lg done\">+L</span>\n      <span class=\"step-badge-lg blinking\" data-vt-badge>-VT</span>\n      <span class=\"step-badge-lg\">4P</span>\n      <span class=\"step-badge-lg\">PC</span>\n    </div>\n\n    <div id=\"exchangeAfterVtTestIdle\">\n      <div class=\"progress-menu-desc\">VT 감압 시험 구간을 준비하는 중입니다...</div>\n      <div class=\"sub-seq-last-alarm\" id=\"exchangeAfterVtTestLastAlarm\"></div>\n      <div class=\"purge-count-panel\" id=\"exchangeAfterVtTestIdleCycleInfo\" style=\"display:none;\">\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">설정시간(분) :</span>\n          <span class=\"purge-count-box\">[ <span id=\"exchangeAfterVtTestIdleCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">진행시간(분) :</span>\n          <span class=\"purge-count-box\">[ <span id=\"exchangeAfterVtTestIdleCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"exchangeAfterVtTestExecuteBtn\" style=\"margin:0;\">실행</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterVtTestIdleCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterVtTestIdleTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterVtTestIdleExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterVtTestIdleExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"exchangeAfterVtTestIdleExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n\n    <div id=\"exchangeAfterVtTestPanel\" style=\"display:none;\">\n      <div class=\"sub-seq-step-label\" id=\"exchangeAfterVtTestStepLabel\">Main 1 - Sub 1</div>\n      <div class=\"sub-seq-operation\" id=\"exchangeAfterVtTestOperation\">-</div>\n      <div class=\"sub-seq-message\" id=\"exchangeAfterVtTestMessage\">-</div>\n      <div class=\"sub-seq-valve-diff\" id=\"exchangeAfterVtTestValveDiff\"></div>\n      <div class=\"sub-seq-timer\" id=\"exchangeAfterVtTestTimer\">-</div>\n      <div class=\"sub-seq-acc-time\" id=\"exchangeAfterVtTestAccTime\">누적 경과시간: 0초</div>\n      <div class=\"sub-seq-alarm-banner\" id=\"exchangeAfterVtTestAlarmBanner\" style=\"display:none;\">\n        <div class=\"sub-seq-last-alarm\" id=\"exchangeAfterVtTestPanelAlarmMsg\"></div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"purge-count-panel\" id=\"exchangeAfterVtTestCycleInfo\" style=\"display:none;\">\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">설정시간(분) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangeAfterVtTestCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">진행시간(분) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangeAfterVtTestCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n        </div>\n        <!-- 초기값/현재값(VT_{side})은 3단계(VT 점검/누출시험, Step 21)에 도달했을 때부터\n             표시된다. \"설정 값\"은 지금 감시 중인 Step의 비교 기준을 그대로 보여준다\n             (subSeqSetSettingValue - 2단계엔 진공 상한, 3단계엔 초기값+누출허용범위). -->\n        <div class=\"purge-count-panel value-panel\">\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">설정 값 :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangeAfterVtTestSetValue\" class=\"purge-count-value\" style=\"min-width:44px;\">0.000</span> ] Torr</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">초기 값 :</span>\n            <span class=\"purge-count-box initial-value\">[ <span id=\"exchangeAfterVtTestInitialValue\" class=\"purge-count-value\" style=\"min-width:44px;\">--</span> ] Torr</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">현재 값 :</span>\n            <span class=\"purge-count-box current-value\">[ <span id=\"exchangeAfterVtTestCurrentValue\" class=\"purge-count-value\" style=\"min-width:44px;\">--</span> ] Torr</span>\n          </div>\n        </div>\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"exchangeAfterVtTestAckBtn\" style=\"margin:0; display:none;\">확인</button>\n          <!-- 평소엔 \"취소\", 알람 배너가 떠 있는 동안엔 \"실행\"으로 바뀌어 재시작을 담당한다. -->\n          <!-- 테스트용 - 카운트다운/누적시간을 그 자리에서 멈추고 남은 시간부터 이어서\n               재개할 수 있다. -->\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterVtTestPauseBtn\" style=\"margin:0;\">일시정지</button>\n          <!-- 테스트 기간 전용 - Step 1부터 즉시 다시 시작한다(사용자 요청). -->\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterVtTestResetBtn\" style=\"margin:0;\">초기화</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterVtTestCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterVtTestTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <!-- 이 구간(VT 감압시험)에 연결된 서브시퀀스(AfterVtTest_v1)를 엑셀로 내보내서 편집하고,\n             편집한 파일을 다시 불러와 그대로 반영한다(gms-sub-sequence-runner.js). -->\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterVtTestExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterVtTestExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"exchangeAfterVtTestExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","교환후3P_배관청소.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>3차 배관청소 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 자동 진행\" 화면 분리 파일 - 용기교체(CC) 완료 다음,\n     \"교환후\" 자동 진행의 첫 번째 화면(Status \"3P\" - 3P → +L → [VT 옵션] → 4P 순서).\n     서브시퀀스 엑셀 엔진(gms-sub-sequence-runner.js, ns='afterThreeP')으로 실행 - 사용자\n     확인(2026-08-09): 교환전 2P(twoP)와 완전히 동일한 구조. 실제 내용은\n     data/gmsSubSequences/AfterThreeP_v1.json(TwoP_v1.json 값 그대로 복제, 반복 종료 CONFIG만\n     \"교환 후 1차 Purge 횟수_{side}\"). 완료되면 곧장 다음 화면(+L 가압시험)으로 넘어간다\n     (VT 분기 없음). 스타일은 ../gms.css를 그대로 참조(복사 아님). gms.js가 fetch해서\n     id=\"progressExchangeThirdPurgeBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressExchangeThirdPurgeBody\">\n    <div class=\"step-badges-lg\">\n      <span class=\"step-badge-lg blinking\">3P</span>\n      <span class=\"step-badge-lg\">+L</span>\n      <span class=\"step-badge-lg\" data-vt-badge>-VT</span>\n      <span class=\"step-badge-lg\">4P</span>\n      <span class=\"step-badge-lg\">PC</span>\n    </div>\n\n    <div id=\"exchangeThirdPurgeIdle\">\n      <div class=\"progress-menu-desc\">3차 배관청소 구간을 준비하는 중입니다...</div>\n      <div class=\"sub-seq-last-alarm\" id=\"exchangeThirdPurgeLastAlarm\"></div>\n      <div class=\"purge-count-panel\" id=\"exchangeThirdPurgeIdleCycleInfo\" style=\"display:none;\">\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">설정 횟수 :</span>\n          <span class=\"purge-count-box\">[ <span id=\"exchangeThirdPurgeIdleCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">진행 횟수 :</span>\n          <span class=\"purge-count-box\">[ <span id=\"exchangeThirdPurgeIdleCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"exchangeThirdPurgeExecuteBtn\" style=\"margin:0;\">실행</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeThirdPurgeIdleCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeThirdPurgeIdleTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeThirdPurgeIdleExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeThirdPurgeIdleExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"exchangeThirdPurgeIdleExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n\n    <div id=\"exchangeThirdPurgePanel\" style=\"display:none;\">\n      <div class=\"sub-seq-step-label\" id=\"exchangeThirdPurgeStepLabel\">Main 1 - Sub 1</div>\n      <div class=\"sub-seq-operation\" id=\"exchangeThirdPurgeOperation\">-</div>\n      <div class=\"sub-seq-message\" id=\"exchangeThirdPurgeMessage\">-</div>\n      <div class=\"sub-seq-valve-diff\" id=\"exchangeThirdPurgeValveDiff\"></div>\n      <div class=\"sub-seq-timer\" id=\"exchangeThirdPurgeTimer\">-</div>\n      <div class=\"sub-seq-acc-time\" id=\"exchangeThirdPurgeAccTime\">누적 경과시간: 0초</div>\n      <div class=\"sub-seq-alarm-banner\" id=\"exchangeThirdPurgeAlarmBanner\" style=\"display:none;\">\n        <div class=\"sub-seq-last-alarm\" id=\"exchangeThirdPurgePanelAlarmMsg\"></div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"purge-count-panel\" id=\"exchangeThirdPurgeCycleInfo\" style=\"display:none;\">\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">설정 횟수 :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangeThirdPurgeCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">진행 횟수 :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangeThirdPurgeCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n        </div>\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"exchangeThirdPurgeAckBtn\" style=\"margin:0; display:none;\">확인</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeThirdPurgePauseBtn\" style=\"margin:0;\">일시정지</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeThirdPurgeResetBtn\" style=\"margin:0;\">초기화</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeThirdPurgeCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeThirdPurgeTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeThirdPurgeExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeThirdPurgeExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"exchangeThirdPurgeExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","교환후4P_배관청소.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>4차 배관청소 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 자동 진행\" 화면 분리 파일 - \"교환후\" 자동 진행의 네 번째\n     (현재 마지막) 화면(Status \"4P\" - 3P → +L → -VT → 4P 순서) - VT 사용 옵션에 따라 +L\n     가압시험 또는 VT 감압시험(-VT) 다음에 들어온다. 서브시퀀스 엑셀 엔진\n     (gms-sub-sequence-runner.js, ns='afterFourP')으로 실행 - 사용자 확인(2026-08-09): 3P와\n     완전히 동일한 구조(TwoP_v1.json 복제). 실제 내용은 data/gmsSubSequences/AfterFourP_v1.json\n     (반복 종료 CONFIG만 \"교환 후 2차 Purge 횟수_{side}\"). 완료 시 PASSWORD\n     (exchangeFourthPurgeDone) 재확인 후 다음 Status(PC, 퍼지완료/가스공급 메뉴)로 넘어간다.\n     스타일은 ../gms.css를 그대로 참조(복사 아님). gms.js가 fetch해서\n     id=\"progressExchangeFourthPurgeBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressExchangeFourthPurgeBody\">\n    <div class=\"step-badges-lg\">\n      <span class=\"step-badge-lg done\">3P</span>\n      <span class=\"step-badge-lg done\">+L</span>\n      <span class=\"step-badge-lg done\" data-vt-badge>-VT</span>\n      <span class=\"step-badge-lg blinking\">4P</span>\n      <span class=\"step-badge-lg\">PC</span>\n    </div>\n\n    <div id=\"exchangeFourthPurgeIdle\">\n      <div class=\"progress-menu-desc\">4차 배관청소 구간을 준비하는 중입니다...</div>\n      <div class=\"sub-seq-last-alarm\" id=\"exchangeFourthPurgeLastAlarm\"></div>\n      <div class=\"purge-count-panel\" id=\"exchangeFourthPurgeIdleCycleInfo\" style=\"display:none;\">\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">설정 횟수 :</span>\n          <span class=\"purge-count-box\">[ <span id=\"exchangeFourthPurgeIdleCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">진행 횟수 :</span>\n          <span class=\"purge-count-box\">[ <span id=\"exchangeFourthPurgeIdleCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"exchangeFourthPurgeExecuteBtn\" style=\"margin:0;\">실행</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeFourthPurgeIdleCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeFourthPurgeIdleTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeFourthPurgeIdleExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeFourthPurgeIdleExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"exchangeFourthPurgeIdleExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n\n    <div id=\"exchangeFourthPurgePanel\" style=\"display:none;\">\n      <div class=\"sub-seq-step-label\" id=\"exchangeFourthPurgeStepLabel\">Main 1 - Sub 1</div>\n      <div class=\"sub-seq-operation\" id=\"exchangeFourthPurgeOperation\">-</div>\n      <div class=\"sub-seq-message\" id=\"exchangeFourthPurgeMessage\">-</div>\n      <div class=\"sub-seq-valve-diff\" id=\"exchangeFourthPurgeValveDiff\"></div>\n      <div class=\"sub-seq-timer\" id=\"exchangeFourthPurgeTimer\">-</div>\n      <div class=\"sub-seq-acc-time\" id=\"exchangeFourthPurgeAccTime\">누적 경과시간: 0초</div>\n      <div class=\"sub-seq-alarm-banner\" id=\"exchangeFourthPurgeAlarmBanner\" style=\"display:none;\">\n        <div class=\"sub-seq-last-alarm\" id=\"exchangeFourthPurgePanelAlarmMsg\"></div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"purge-count-panel\" id=\"exchangeFourthPurgeCycleInfo\" style=\"display:none;\">\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">설정 횟수 :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangeFourthPurgeCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">진행 횟수 :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangeFourthPurgeCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n        </div>\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"exchangeFourthPurgeAckBtn\" style=\"margin:0; display:none;\">확인</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeFourthPurgePauseBtn\" style=\"margin:0;\">일시정지</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeFourthPurgeResetBtn\" style=\"margin:0;\">초기화</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeFourthPurgeCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeFourthPurgeTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeFourthPurgeExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeFourthPurgeExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"exchangeFourthPurgeExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","교환후_Puls2.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>교환후 Puls 2 - GMS 조작화면</title>\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressExchangeAfterPulsBody\">\n    <div class=\"step-badges-lg\">\n      <span class=\"step-badge-lg done\">3P</span>\n      <span class=\"step-badge-lg blinking\">+L</span>\n      <span class=\"step-badge-lg\" data-vt-badge>-VT</span>\n      <span class=\"step-badge-lg\">4P</span>\n      <span class=\"step-badge-lg\">PC</span>\n    </div>\n\n    <div id=\"exchangeAfterPulsIdle\">\n      <div class=\"progress-menu-desc\">교환 후 Puls 2 구간을 준비하는 중입니다...</div>\n      <div class=\"sub-seq-last-alarm\" id=\"exchangeAfterPulsLastAlarm\"></div>\n      <div class=\"purge-count-panel\" id=\"exchangeAfterPulsIdleCycleInfo\" style=\"display:none;\">\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">설정 횟수 :</span>\n          <span class=\"purge-count-box\">[ <span id=\"exchangeAfterPulsIdleCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">진행 횟수 :</span>\n          <span class=\"purge-count-box\">[ <span id=\"exchangeAfterPulsIdleCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"exchangeAfterPulsExecuteBtn\" style=\"margin:0;\">실행</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterPulsIdleCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterPulsIdleTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterPulsIdleExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterPulsIdleExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"exchangeAfterPulsIdleExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n\n    <div id=\"exchangeAfterPulsPanel\" style=\"display:none;\">\n      <div class=\"sub-seq-step-label\" id=\"exchangeAfterPulsStepLabel\">Main 14 - Sub 1</div>\n      <div class=\"sub-seq-operation\" id=\"exchangeAfterPulsOperation\">-</div>\n      <div class=\"sub-seq-message\" id=\"exchangeAfterPulsMessage\">-</div>\n      <div class=\"sub-seq-valve-diff\" id=\"exchangeAfterPulsValveDiff\"></div>\n      <div class=\"sub-seq-timer\" id=\"exchangeAfterPulsTimer\">-</div>\n      <div class=\"sub-seq-acc-time\" id=\"exchangeAfterPulsAccTime\">누적 경과시간: 0초</div>\n      <div class=\"sub-seq-alarm-banner\" id=\"exchangeAfterPulsAlarmBanner\" style=\"display:none;\">\n        <div class=\"sub-seq-last-alarm\" id=\"exchangeAfterPulsPanelAlarmMsg\"></div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"purge-count-panel\" id=\"exchangeAfterPulsCycleInfo\" style=\"display:none;\">\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">설정 횟수 :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangeAfterPulsCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">진행 횟수 :</span>\n            <span class=\"purge-count-box\">[ <span id=\"exchangeAfterPulsCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n        </div>\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"exchangeAfterPulsAckBtn\" style=\"margin:0; display:none;\">확인</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterPulsPauseBtn\" style=\"margin:0;\">일시정지</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterPulsResetBtn\" style=\"margin:0;\">초기화</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterPulsCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterPulsTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterPulsExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"exchangeAfterPulsExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"exchangeAfterPulsExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","누출 시험.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>수동 누출 시험 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 수동 누출 시험\"(누출 시험 종류 선택) 화면 분리 파일 -\n     Maintenance Purge 화면의 \"누출 시험\" 버튼으로 들어온다. 배관 청소 화면(현재\n     \"수동 배관 청소.html\", 헤더 \"[A] 수동 배관 청소\")과는 별도 화면이라 파일도 분리했다.\n     스타일은 ../gms.css를 그대로 참조(복사 아님). gms.js가 fetch해서\n     id=\"progressLeakTestBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <!-- 누출 시험 종류 선택 - VT 감압 시험/PT 감압 시험/가압 시험 중 하나를 고르고 확인.\n       실제 시퀀스 로직은 아직 없음(뼈대) - 선택 상태(강조 표시)만 실제로 동작하고,\n       확인은 토스트만 뜬다. 취소는 이미지에는 없지만 다른 화면들과의 일관성을 위해\n       추가했다(Maintenance Purge 화면으로 되돌아감). -->\n  <div class=\"progress-menu-body\" id=\"progressLeakTestBody\">\n    <div class=\"progress-menu-desc\">진행할 메뉴들<br>선택 하십시오.</div>\n    <div class=\"progress-btn-group\">\n      <button type=\"button\" class=\"progress-btn leak-test-btn\" data-leak-test=\"VT 감압 시험\">VT 감압 시험</button>\n      <button type=\"button\" class=\"progress-btn leak-test-btn\" data-leak-test=\"PT 감압 시험\">PT 감압 시험</button>\n      <button type=\"button\" class=\"progress-btn leak-test-btn\" data-leak-test=\"가압 시험\">가압 시험</button>\n      <div style=\"display:flex;gap:10px;margin-top:14px;\">\n        <button type=\"button\" class=\"progress-btn\" id=\"leakTestConfirmBtn\" style=\"flex:1;margin-bottom:0;\">확인</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"leakTestCancelBtn\" style=\"flex:1;margin-top:0;\">취소</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","메인 메뉴.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>메인 메뉴 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 메인 메뉴\" 화면 분리 파일. 스타일은 ../gms.css를 그대로\n     참조(복사 아님). gms.js가 fetch해서 id=\"progressMainMenuBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <!-- \"A 진행\"/\"B 진행\" 클릭 시 나타나는 하위 메뉴 - 순간정전 매뉴얼의 \"[A] 메인 메뉴\"\n       화면 구성을 그대로 따른다(가스공급/실린더 교환/반대쪽 선택/유지보수/TREND).\n       실제 동작 로직은 아직 없음 - 화면 전환(취소/\"반대쪽\" 선택)만 실제로 동작한다. -->\n  <div class=\"progress-menu-body\" id=\"progressMainMenuBody\">\n    <div class=\"progress-menu-desc\">진행할 메뉴를 선택 하십시오!</div>\n    <!-- 버튼 묶음은 프레임 맨 아래에 붙는다(margin-top:auto) - 조작화면의 모든\n         하위 화면 공통 규칙, root 화면(progressRootBody)과 동일 패턴. -->\n    <div class=\"progress-btn-group\">\n      <button type=\"button\" class=\"progress-btn\" id=\"mainMenuCylinderExchangeBtn\" data-action=\"실린더 교환\">실린더 교환</button>\n      <button type=\"button\" class=\"progress-btn\" id=\"mainMenuSwitchSideBtn\">\"B\" 선택</button>\n      <button type=\"button\" class=\"progress-btn\" id=\"mainMenuMaintenanceEntryBtn\" data-action=\"유지 보수\">유지 보수</button>\n      <button type=\"button\" class=\"progress-btn\" id=\"mainMenuTrendBtn\" data-action=\"TREND\">TREND</button>\n      <div style=\"display:flex;gap:10px;margin-top:14px;\">\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"mainMenuAuxBtn\" style=\"flex:1;\">보조 메뉴</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"mainMenuCancelBtn\" style=\"flex:1;\">취소</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","설정모드.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>설정모드 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 설정모드\" 화면 분리 파일. 보조 메뉴의 \"설정모드 A\"/\"설정모드 B\"\n     버튼으로 들어온다(Operation.js의 auxMenuConfigModeABtn/BBtn → requestConfigMode(side) →\n     showProgressConfigMode(side), \"조정모드 A/B\"와 동일한 패턴 - 버튼 2개가 화면 1개를 공유하고\n     side를 명시적으로 넘긴다). CONFIG 탭(엔지니어용, data/gmsSubSequenceConfig.json 전체 편집)과\n     같은 데이터를 보되, 이 화면은 side(A/B/공통)와 OPTION 표시여부로 걸러서 조작자가 키패드로\n     빠르게 값만 바꾸는 용도다. 그리드는 gms-configmode-widget.js(Univer, 값이 많을 때 2/3/4단\n     레이아웃으로 나눠 보임), 키패드/저장/A값복사/단수전환은 gms-configmode-tab.js가 전담한다\n     (gms-pt-calibration.js와 같은 관심사 분리 패턴). 스타일은 ../gms.css를 그대로 참조. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressConfigModeBody\">\n    <div class=\"progress-menu-desc\">설정값을 확인하고 우측 키패드로 값을 바꿉니다. 변경한 행은 빨간색으로 표시되며, \"저장\"을 눌러야 실제 반영됩니다.</div>\n    <div class=\"config-mode-toolbar\">\n      <div class=\"config-mode-cols-group\">\n        <span>보기</span>\n        <button type=\"button\" class=\"config-mode-cols-btn\" id=\"configModeCols1Btn\">1단</button>\n        <button type=\"button\" class=\"config-mode-cols-btn\" id=\"configModeCols2Btn\">2단</button>\n        <button type=\"button\" class=\"config-mode-cols-btn\" id=\"configModeCols3Btn\">3단</button>\n        <button type=\"button\" class=\"config-mode-cols-btn\" id=\"configModeCols4Btn\">4단</button>\n      </div>\n      <button type=\"button\" id=\"configModeRefreshBtn\">🔄 새로고침</button>\n      <button type=\"button\" id=\"configModeCopyBtn\" style=\"display:none;\">⇄ A값 전체 복사</button>\n      <button type=\"button\" class=\"primary\" id=\"configModeSaveBtn\" style=\"margin-left:auto;\">저장</button>\n      <button type=\"button\" id=\"configModeCloseBtn\">✕ 닫기</button>\n    </div>\n    <div class=\"config-mode-body\">\n      <div id=\"gmsConfigModeGridContainer\"></div>\n      <div class=\"config-mode-keypad-wrap\" id=\"configModeKeypadWrap\" style=\"display:none;\">\n        <div class=\"pt-calib-keypad-title\" id=\"configModeKeypadTitle\"></div>\n        <div class=\"password-display\" id=\"configModeKeypadDisplay\"></div>\n        <div class=\"config-mode-keypad-range\" id=\"configModeKeypadRange\"></div>\n        <div class=\"config-mode-nav-pad\">\n          <span></span>\n          <button type=\"button\" class=\"keypad-btn keypad-aux\" data-key=\"up\">▲</button>\n          <span></span>\n          <button type=\"button\" class=\"keypad-btn keypad-aux\" data-key=\"left\">◀</button>\n          <span></span>\n          <button type=\"button\" class=\"keypad-btn keypad-aux\" data-key=\"right\">▶</button>\n          <span></span>\n          <button type=\"button\" class=\"keypad-btn keypad-aux\" data-key=\"down\">▼</button>\n          <span></span>\n        </div>\n        <div class=\"password-keypad config-mode-keypad\">\n          <button type=\"button\" class=\"keypad-btn\" data-key=\"7\">7</button>\n          <button type=\"button\" class=\"keypad-btn\" data-key=\"8\">8</button>\n          <button type=\"button\" class=\"keypad-btn\" data-key=\"9\">9</button>\n          <button type=\"button\" class=\"keypad-btn keypad-aux\" data-key=\"bs\">BS</button>\n          <button type=\"button\" class=\"keypad-btn\" data-key=\"4\">4</button>\n          <button type=\"button\" class=\"keypad-btn\" data-key=\"5\">5</button>\n          <button type=\"button\" class=\"keypad-btn\" data-key=\"6\">6</button>\n          <button type=\"button\" class=\"keypad-btn keypad-aux\" data-key=\"clear\">CLEAR</button>\n          <button type=\"button\" class=\"keypad-btn\" data-key=\"1\">1</button>\n          <button type=\"button\" class=\"keypad-btn\" data-key=\"2\">2</button>\n          <button type=\"button\" class=\"keypad-btn\" data-key=\"3\">3</button>\n          <button type=\"button\" class=\"keypad-btn keypad-aux\" data-key=\"esc\">ESC</button>\n          <button type=\"button\" class=\"keypad-btn\" data-key=\"0\">0</button>\n          <button type=\"button\" class=\"keypad-btn\" data-key=\".\">.</button>\n          <button type=\"button\" class=\"keypad-btn\" data-key=\"-\">-</button>\n          <button type=\"button\" class=\"keypad-btn keypad-aux primary\" data-key=\"enter\">ENTER</button>\n        </div>\n      </div>\n    </div>\n    <div class=\"h-splitter\" id=\"gmsConfigModeGridResizeHandle\" title=\"드래그해서 그리드 높이 조절\"></div>\n  </div>\n</body>\n</html>\n","수동 VT 감압시험.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>수동 VT 감압시험 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 수동 VT 감압시험\" 화면 분리 파일 - 누출 시험 화면의\n     \"VT 감압 시험\" 버튼으로 들어온다. 스타일은 ../gms.css를 그대로 참조(복사 아님).\n     gms.js가 fetch해서 id=\"progressVtTestBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <!-- 수동 VT 감압 시험 - 설정시간/진행시간(분)과 설정·초기·현재 압력값(Torr)을 보여준다.\n       실제 시퀀스/측정 로직은 아직 없음(뼈대) - 실행은 \"준비 중\" 토스트만, 진행시간·\n       초기값·현재값은 0(.000) 고정 표시. 취소는 누출 시험 화면으로 되돌아간다. -->\n  <div class=\"progress-menu-body\" id=\"progressVtTestBody\">\n    <div class=\"progress-menu-desc\">수동 VT 감압 시험<br>모드입니다.</div>\n    <div class=\"progress-btn-group\">\n      <div class=\"purge-count-panel\">\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">설정시간 :</span>\n          <span class=\"purge-count-box\">[ <input type=\"number\" id=\"vtTestSetMinutes\" class=\"purge-count-input\" min=\"0\" step=\"1\" value=\"0\" /> ] 분</span>\n        </div>\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">진행시간 :</span>\n          <span class=\"purge-count-box\">[ <span id=\"vtTestProgressMinutes\" class=\"purge-count-value\">0</span> ] 분</span>\n        </div>\n      </div>\n      <div class=\"purge-count-panel value-panel\">\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">설정 값 :</span>\n          <span class=\"purge-count-box\">[ <input type=\"number\" id=\"vtTestSetValue\" class=\"purge-count-input\" style=\"width:64px;\" min=\"0\" step=\"0.001\" value=\"0.000\" /> ] Torr</span>\n        </div>\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">초기 값 :</span>\n          <span class=\"purge-count-box initial-value\">[ <span id=\"vtTestInitialValue\" class=\"purge-count-value\" style=\"min-width:44px;\">0.000</span> ] Torr</span>\n        </div>\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">현재 값 :</span>\n          <span class=\"purge-count-box current-value\">[ <span id=\"vtTestCurrentValue\" class=\"purge-count-value\" style=\"min-width:44px;\">0.000</span> ] Torr</span>\n        </div>\n      </div>\n      <div style=\"display:flex;gap:10px;\">\n        <button type=\"button\" class=\"progress-btn\" id=\"vtTestRunBtn\" style=\"flex:1;margin-bottom:0;\">실행</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"vtTestCancelBtn\" style=\"flex:1;margin-top:0;\">취소</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","수동 가압 시험.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>수동 가압 시험 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 수동 가압 시험\" 화면 분리 파일 - 누출 시험 화면의\n     \"가압 시험\" 버튼으로 들어온다. \"수동 감압 시험.html\"과 구조는 거의 동일하고(HPT\n     4점 초기압력/현재압력 표 재사용), 안내문과 상태 표시줄만 다르다. 스타일은 ../gms.css를\n     그대로 참조(복사 아님). gms.js가 fetch해서 id=\"progressPressureTestBody\" 컨테이너에\n     주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <!-- 수동 가압 시험 - 설정/진행 시간(분)과 HPT 4점의 초기압력/현재압력을 보여준다.\n       실제 시퀀스/측정 로직은 아직 없음(뼈대) - 확인은 \"준비 중\" 토스트만, 진행시간·\n       압력값은 0 고정 표시. 취소는 누출 시험 화면으로 되돌아간다. -->\n  <div class=\"progress-menu-body\" id=\"progressPressureTestBody\">\n    <div class=\"progress-menu-desc\">수동 가압 시험<br>모드입니다.</div>\n    <div class=\"progress-menu-desc pt-test-running\">수동 가압 시험중</div>\n    <div class=\"progress-btn-group\">\n      <div class=\"purge-count-panel\">\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">설정 :</span>\n          <span class=\"purge-count-box\">[ <input type=\"number\" id=\"pressureTestSetMinutes\" class=\"purge-count-input\" min=\"0\" step=\"1\" value=\"0\" /> ]분</span>\n          <span class=\"purge-count-label\">진행 :</span>\n          <span class=\"purge-count-box\">[ <span id=\"pressureTestProgressMinutes\" class=\"purge-count-value\">0</span> ]분</span>\n        </div>\n      </div>\n      <table class=\"pt-test-table\">\n        <thead><tr><th></th><th>초기압력</th><th>현재압력</th></tr></thead>\n        <tbody id=\"pressureTestRows\"></tbody>\n      </table>\n      <div style=\"display:flex;gap:10px;\">\n        <button type=\"button\" class=\"progress-btn\" id=\"pressureTestConfirmBtn\" style=\"flex:1;margin-bottom:0;\">확인</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"pressureTestCancelBtn\" style=\"flex:1;margin-top:0;\">취소</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","수동 감압 시험.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>수동 감압 시험 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 수동 감압 시험\" 화면 분리 파일 - 누출 시험 화면의\n     \"PT 감압 시험\" 버튼으로 들어온다. HPT_A1~A4(또는 B1~B4) 4개 센서의 초기압력/현재압력을\n     보여준다 - 태그는 unit1.json에 아직 없는 자리(뼈대)라 gms.js가 현재 측(A/B)에 맞춰\n     이름만 동적으로 만들고 값은 0 고정 표시한다. 스타일은 ../gms.css를 그대로 참조(복사\n     아님). gms.js가 fetch해서 id=\"progressPtTestBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <!-- 수동 감압 시험 - 설정/진행 시간(분)과 HPT 4점의 초기압력/현재압력을 보여준다.\n       실제 시퀀스/측정 로직은 아직 없음(뼈대) - 확인은 \"준비 중\" 토스트만, 진행시간·\n       압력값은 0 고정 표시. 취소는 누출 시험 화면으로 되돌아간다. -->\n  <div class=\"progress-menu-body\" id=\"progressPtTestBody\">\n    <div class=\"progress-menu-desc\">수동 감압 시험<br>모드입니다.</div>\n    <div class=\"progress-menu-desc pt-test-warn\">실린더를 잠근 후<br>실행하십시오!</div>\n    <div class=\"progress-btn-group\">\n      <div class=\"purge-count-panel\">\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">설정 :</span>\n          <span class=\"purge-count-box\">[ <input type=\"number\" id=\"ptTestSetMinutes\" class=\"purge-count-input\" min=\"0\" step=\"1\" value=\"0\" /> ]분</span>\n          <span class=\"purge-count-label\">진행 :</span>\n          <span class=\"purge-count-box\">[ <span id=\"ptTestProgressMinutes\" class=\"purge-count-value\">0</span> ]분</span>\n        </div>\n      </div>\n      <table class=\"pt-test-table\">\n        <thead><tr><th></th><th>초기압력</th><th>현재압력</th></tr></thead>\n        <tbody id=\"ptTestRows\"></tbody>\n      </table>\n      <div style=\"display:flex;gap:10px;\">\n        <button type=\"button\" class=\"progress-btn\" id=\"ptTestConfirmBtn\" style=\"flex:1;margin-bottom:0;\">확인</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"ptTestCancelBtn\" style=\"flex:1;margin-top:0;\">취소</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","수동 바코드 체크.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>수동 바코드 체크 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 수동 바코드 체크\" 화면 분리 파일 - 유지보수 메뉴 화면의\n     \"바코드 체크\" 버튼으로 들어온다. 실린더 2개(A측이면 A1/A2, B측이면 B1/B2 - 현재 측에\n     맞춰 gms.js가 라벨만 동적으로 바꾼다)의 바코드 스캐너 입력칸을 보여준다. 스타일은\n     ../gms.css를 그대로 참조(복사 아님). gms.js가 fetch해서 id=\"progressBarcodeCheckBody\"\n     컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <!-- 수동 바코드 체크 - 바코드 스캐너로 실린더 바코드를 읽어 입력칸(A1/A2 또는 B1/B2)에\n       채운다(스캐너는 키보드 입력으로 동작하므로 일반 텍스트 입력칸이면 충분하다). 실제\n       검증(Gas name 일치 확인 등) 로직은 아직 없음(뼈대) - 확인은 \"준비 중\" 토스트만.\n       취소는 유지보수 메뉴로 되돌아간다(이미지에는 없지만 다른 화면들과의 일관성을 위해\n       추가). -->\n  <div class=\"progress-menu-body\" id=\"progressBarcodeCheckBody\">\n    <div class=\"barcode-check-title\">[ Gas name 확인 ]</div>\n    <div class=\"barcode-check-desc\">바코드 스캐너를 이용하여<br>실린더 바코드를 읽어 주시기 바랍니다.</div>\n    <div class=\"progress-btn-group\">\n      <div class=\"barcode-input-row\">\n        <span class=\"purge-count-label\" id=\"barcodeLabel1\">A1</span>\n        <input type=\"text\" id=\"barcodeInput1\" class=\"barcode-input\" placeholder=\"바코드 스캔\" />\n      </div>\n      <div class=\"barcode-input-row\">\n        <span class=\"purge-count-label\" id=\"barcodeLabel2\">A2</span>\n        <input type=\"text\" id=\"barcodeInput2\" class=\"barcode-input\" placeholder=\"바코드 스캔\" />\n      </div>\n      <div class=\"barcode-check-warn\">N.G시 담당자에게<br>연락 하시기 바랍니다.</div>\n      <div style=\"display:flex;gap:10px;\">\n        <button type=\"button\" class=\"progress-btn\" id=\"barcodeCheckConfirmBtn\" style=\"flex:1;margin-bottom:0;\">확인</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"barcodeCheckCancelBtn\" style=\"flex:1;margin-top:0;\">취소</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","수동 배관 청소.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>수동 배관 청소 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 수동 배관 청소\" 화면 분리 파일 - Maintenance Purge 화면의\n     \"배관 청소\" 버튼으로 들어온다(\"유지보수 메뉴.html\"의 PASSWORD 게이트와는 다른 화면).\n     스타일은 ../gms.css를 그대로 참조(복사 아님). gms.js가 fetch해서\n     id=\"progressPipeCleanBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <!-- 수동 배관 청소 - 설정 횟수만큼 청소 시퀀스를 반복하는 화면(뼈대). 실제 시퀀스/횟수\n       카운트 로직은 아직 없음 - 확인은 \"준비 중\" 토스트만 뜨고, 진행 횟수는 0 고정 표시. -->\n  <div class=\"progress-menu-body\" id=\"progressPipeCleanBody\">\n    <div class=\"progress-menu-desc\">수동 배관 청소<br>모드입니다.</div>\n    <div class=\"progress-menu-desc\" style=\"margin-top: 22px;\">실린더를 잠근 후<br>실행하십시오!</div>\n    <div class=\"progress-btn-group\">\n      <div class=\"purge-count-panel\">\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">설정 횟수 :</span>\n          <span class=\"purge-count-box\">[ <input type=\"number\" id=\"pipeCleanSetCount\" class=\"purge-count-input\" min=\"0\" step=\"1\" value=\"0\" /> ]</span>\n        </div>\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">진행 횟수 :</span>\n          <span class=\"purge-count-box\">[ <span id=\"pipeCleanProgressCount\" class=\"purge-count-value\">0</span> ]</span>\n        </div>\n      </div>\n      <div style=\"display:flex;gap:10px;\">\n        <button type=\"button\" class=\"progress-btn\" id=\"pipeCleanConfirmBtn\" style=\"flex:1;margin-bottom:0;\">확인</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"pipeCleanCancelBtn\" style=\"flex:1;margin-top:0;\">취소</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","수동 밸브 조작.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>수동 밸브 조작 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 수동 밸브 조작\" 화면 분리 파일. 스타일은 ../gms.css를\n     그대로 참조(복사 아님). gms.js가 fetch해서 id=\"progressManualValveBody\" 컨테이너에\n     주입한 뒤, renderManualValveGrid()가 #manualValveGrid 안을 실제 밸브 버튼으로 채운다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <!-- 수동밸브 조작 - 유지보수 메뉴의 첫 항목. A/B측 전용 밸브(_A/_B 접미사, AG 포함)와\n       공통 밸브(HPIV/PIV/PNV/PNBV/GNV/VN1/VN2)를 3열 격자로 배치, 우측에 Q/C(PT 이력 로그)/\n       취소/확인 버튼을 둔다. unit1.json의 밸브 25개 전부가 실제 점멸+확인+쓰기로 동작한다\n       (인터락 로직은 다음 단계). 행 수는 항목 개수에 맞춰 자동이고(.valve-grid의\n       grid-auto-rows:1fr), 세로 폭은 항상 균등하다. H/T는 밸브가 아니라 히터 조작\n       화면(히터 조작.html)으로 넘어가는 버튼이다. -->\n\n  <div class=\"progress-menu-body\" id=\"progressManualValveBody\">\n    <div class=\"valve-grid-layout\">\n      <div class=\"valve-grid\" id=\"manualValveGrid\"></div>\n      <div class=\"valve-grid-side-actions\">\n        <button type=\"button\" class=\"valve-side-btn\" id=\"manualValveQcBtn\" style=\"flex:2;\">Q<br>/<br>C</button>\n        <button type=\"button\" class=\"valve-side-btn\" id=\"manualValveCancelBtn\" style=\"flex:2;\">취소</button>\n        <button type=\"button\" class=\"valve-side-btn primary\" id=\"manualValveConfirmBtn\" style=\"flex:1;\">확인</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","시퀀스_Bypass.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>배관 By-pass 체크 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 자동 진행\" 화면 분리 파일 - Status \"Bypass\"(배관 By-pass\n     체크). 3P 배관청소 다음 가압시험(+L)과 동일한 서브시퀀스 가압/감압 화면 디자인 구조.\n     서브시퀀스 엑셀 엔진(gms-sub-sequence-runner.js, ns='bypass')으로 실행.\n     완료되면 다음 Status(+L)로 넘어간다. 스타일은 ../gms.css를 그대로 참조.\n     gms.js가 fetch해서 id=\"progressSequenceBypassBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressSequenceBypassBody\">\n    <div class=\"step-badges-lg\">\n      <span class=\"step-badge-lg done\">3P</span>\n      <span class=\"step-badge-lg blinking\">+L</span>\n      <span class=\"step-badge-lg\" data-vt-badge>-VT</span>\n      <span class=\"step-badge-lg\">4P</span>\n      <span class=\"step-badge-lg\">PC</span>\n    </div>\n\n    <div id=\"sequenceBypassIdle\">\n      <div class=\"progress-menu-desc\">배관 By-pass 체크 구간을 준비하는 중입니다...</div>\n      <div class=\"sub-seq-last-alarm\" id=\"sequenceBypassLastAlarm\"></div>\n      <div class=\"purge-count-panel\" id=\"sequenceBypassIdleCycleInfo\" style=\"display:none;\">\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">설정시간(분) :</span>\n          <span class=\"purge-count-box\">[ <span id=\"sequenceBypassIdleCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">진행시간(분) :</span>\n          <span class=\"purge-count-box\">[ <span id=\"sequenceBypassIdleCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n        </div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"sequenceBypassExecuteBtn\" style=\"margin:0;\">실행</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"sequenceBypassIdleCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"sequenceBypassIdleTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"sequenceBypassIdleExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"sequenceBypassIdleExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"sequenceBypassIdleExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n\n    <div id=\"sequenceBypassPanel\" style=\"display:none;\">\n      <div class=\"sub-seq-step-label\" id=\"sequenceBypassStepLabel\">Main 1 - Sub 1</div>\n      <div class=\"sub-seq-operation\" id=\"sequenceBypassOperation\">-</div>\n      <div class=\"sub-seq-message\" id=\"sequenceBypassMessage\">-</div>\n      <div class=\"sub-seq-valve-diff\" id=\"sequenceBypassValveDiff\"></div>\n      <div class=\"sub-seq-timer\" id=\"sequenceBypassTimer\">-</div>\n      <div class=\"sub-seq-acc-time\" id=\"sequenceBypassAccTime\">누적 경과시간: 0초</div>\n      <div class=\"sub-seq-alarm-banner\" id=\"sequenceBypassAlarmBanner\" style=\"display:none;\">\n        <div class=\"sub-seq-last-alarm\" id=\"sequenceBypassPanelAlarmMsg\"></div>\n      </div>\n      <div class=\"progress-btn-group\">\n        <!-- 초기값/현재값(HPT_{side})은 안정화 대기 Step에 최초 도달했을 때부터 표시된다\n             (가압시험 화면과 동일한 구성). -->\n        <div class=\"purge-count-panel\" id=\"sequenceBypassCycleInfo\" style=\"display:none;\">\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\" id=\"sequenceBypassInitialLabel\">초기값(NPT) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"sequenceBypassCaptureInitial\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\" id=\"sequenceBypassCurrentLabel\">현재값(NPT) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"sequenceBypassCaptureCurrent\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">압력변동기준 :</span>\n            <span class=\"purge-count-box\">[ <span id=\"sequenceBypassCaptureLimit\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">설정시간(분) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"sequenceBypassCycleTarget\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n          <div class=\"purge-count-row\">\n            <span class=\"purge-count-label\">진행시간(분) :</span>\n            <span class=\"purge-count-box\">[ <span id=\"sequenceBypassCycleCurrent\" class=\"purge-count-value\">-</span> ]</span>\n          </div>\n        </div>\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"sequenceBypassAckBtn\" style=\"margin:0; display:none;\">확인</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"sequenceBypassPauseBtn\" style=\"margin:0;\">일시정지</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"sequenceBypassResetBtn\" style=\"margin:0;\">초기화</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"sequenceBypassCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"sequenceBypassTrendBtn\" style=\"margin:0;\">TREND</button>\n        </div>\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"sequenceBypassExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"sequenceBypassExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"sequenceBypassExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","시퀀스_Puls.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>잔류가스 제거(Puls Vent) - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 자동 진행\" 화면 분리 파일 - Main Sequence.csv에는 있지만\n     기존 앱엔 화면이 없던 \"Puls\"(잔류가스 제거/Puls Vent) 단계. Main 시퀀스 순서 편집기로\n     순서에 넣고 적용 처리해야만 실제 흐름에 나타난다(advanceToNextEnabledStatus,\n     Operation.js). 아직 실기 연동 전이라 안내문+실행/취소/TREND 뼈대만 있다. 스타일은\n     ../gms.css를 그대로 참조. gms.js가 fetch해서 id=\"progressSequencePulsBody\" 컨테이너에\n     주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressSequencePulsBody\">\n    <div class=\"progress-menu-desc\">잔류가스 제거(Puls Vent) 진행 중</div>\n    <div class=\"progress-btn-group\">\n      <div style=\"display:flex;gap:10px;\">\n        <button type=\"button\" class=\"progress-btn\" id=\"sequencePulsRunBtn\" style=\"flex:1;margin-bottom:0;\">실행</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"sequencePulsCancelBtn\" style=\"flex:1;margin-top:0;\">취소</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"sequencePulsTrendBtn\" style=\"flex:1;margin-top:0;\">TREND</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","시퀀스_RGV.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Real Gas Vent - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 자동 진행\" 화면 분리 파일 - Main Sequence.csv에는 있지만\n     기존 앱엔 화면이 없던 \"RGV\"(Real Gas Vent) 단계. Main 시퀀스 순서 편집기로 순서에\n     넣고 적용 처리해야만 실제 흐름에 나타난다(advanceToNextEnabledStatus, Operation.js).\n     아직 실기 연동 전이라 안내문+실행/취소/TREND 뼈대만 있다. 스타일은 ../gms.css를 그대로\n     참조. gms.js가 fetch해서 id=\"progressSequenceRgvBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressSequenceRgvBody\">\n    <div class=\"progress-menu-desc\">Real Gas Vent 진행 중</div>\n    <div class=\"progress-btn-group\">\n      <div style=\"display:flex;gap:10px;\">\n        <button type=\"button\" class=\"progress-btn\" id=\"sequenceRgvRunBtn\" style=\"flex:1;margin-bottom:0;\">실행</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"sequenceRgvCancelBtn\" style=\"flex:1;margin-top:0;\">취소</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"sequenceRgvTrendBtn\" style=\"flex:1;margin-top:0;\">TREND</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","압력 조정 모드.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>압력 조정 모드 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 압력 조정 모드\" 화면 분리 파일. 스타일은 ../gms.css를 그대로\n     참조(복사 아님). gms.js가 fetch해서 id=\"progressAdjustModeBody\" 컨테이너에 주입한다.\n     보조 메뉴의 \"조정모드 A/B\" → PASSWORD 게이트(adjustMode) 통과 후 들어오는 화면(참고\n     이미지: 실제 장비 HMI를 그대로 재현했던 팝업을 유지보수 메뉴와 동일하게 진짜 화면\n     전환으로 바꿨다 - Operation.js의 requestAdjustMode/showProgressAdjustMode 참고).\n     가스공급 중(Status=Service)인 side는 인터락으로 아예 진입 자체가 막힌다(요청사항) -\n     requestAdjustMode에서 화면 전환 전에 미리 걸러진다.\n\n     \"실행\" 버튼은 서브시퀀스 실행 엔진(public/gms-sub-sequence-runner.js,\n     window.startSubSequenceRunner('AdjustMode', side))을 시작한다 - 어떤 서브시퀀스를\n     쓸지는 data/gmsSubSequenceSelection.json의 \"AdjustMode\" 매핑(기본값 AdjustMode_v1\n     샘플)을 그대로 따른다. 진행 중에는 #adjustModeSeqPanel이 #adjustModeSeqIdle을\n     대신해서 보인다(런너가 직접 토글). -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressAdjustModeBody\">\n    <div id=\"adjustModeSeqIdle\">\n      <div class=\"progress-menu-desc\">PT Sensor 압력 조정을<br>진행하는 모드입니다.</div>\n      <!-- 알람으로 초기화되면 여기 idle로 돌아오는데, 예전엔 메시지 없이 조용히 돌아와서\n           운영자가 원인을 알 수 없었다(Puls/1P와 같은 문제 - 사용자 요청으로 조정모드도\n           함께 확인해 맞춤). \"실행\"을 다시 누르면 지워진다. -->\n      <div class=\"sub-seq-last-alarm\" id=\"subSeqLastAlarm\"></div>\n      <div class=\"progress-btn-group\">\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"adjustModeExecuteBtn\" style=\"margin:0;\">실행</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"adjustModeCancelBtn\" style=\"margin:0;\">취소</button>\n          <button type=\"button\" class=\"progress-btn\" id=\"adjustModePressureBtn\" style=\"margin:0;\">압력조정</button>\n        </div>\n        <!-- 조정모드에 연결된 서브시퀀스(AdjustMode_v1)를 엑셀로 내보내서 편집하고, 편집한\n             파일을 다시 불러와 그대로 반영한다(public/gms-sub-sequence-runner.js). -->\n        <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"subSeqExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"subSeqExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n        </div>\n        <input type=\"file\" id=\"subSeqExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n      </div>\n    </div>\n\n    <div id=\"adjustModeSeqPanel\" style=\"display:none;\">\n      <div class=\"sub-seq-step-label\" id=\"subSeqStepLabel\">Main 1 - Sub 1</div>\n      <div class=\"sub-seq-operation\" id=\"subSeqOperation\">-</div>\n      <div class=\"sub-seq-message\" id=\"subSeqMessage\">-</div>\n      <div class=\"sub-seq-valve-diff\" id=\"subSeqValveDiff\"></div>\n      <div class=\"sub-seq-timer\" id=\"subSeqTimer\">-</div>\n      <div class=\"sub-seq-acc-time\" id=\"subSeqAccTime\">누적 경과시간: 0초</div>\n      <!-- Cycle(엑셀 E열 \"LOOP:되돌아갈Step:반복횟수\" 지시문)이 있는 서브시퀀스에서만 보인다\n           (gms-sub-sequence-runner.js의 subSeqRenderCycleStatus) - 반복 구간이 없는 서브시퀀스는\n           숨겨진 채로 유지된다. -->\n      <div class=\"sub-seq-cycle-info\" id=\"subSeqCycleInfo\" style=\"display:none;\">설정 횟수: <span id=\"subSeqCycleTarget\">-</span>회 / 진행 횟수: <span id=\"subSeqCycleCurrent\">-</span>회</div>\n      <div class=\"progress-btn-group\">\n        <div class=\"adjust-mode-actions\">\n          <button type=\"button\" class=\"progress-btn\" id=\"subSeqAckBtn\" style=\"margin:0; display:none;\">확인</button>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"subSeqStopBtn\" style=\"margin:0;\">중지</button>\n        </div>\n        <!-- 실제 알람 신호가 아직 없어(다른 화면들과 동일한 임시 상태) Alarm Seq. 1/2/3\n             대응 동작을 가상으로 검증하는 테스트 컨트롤(public/gms-sub-sequence-runner.js\n             subSeqHandleAlarm). 1=초기화, 2=이어서 재진행 대기, 3=SHUTDOWN(메인 화면 이동). -->\n        <div class=\"adjust-mode-actions sub-seq-alarm-test\" style=\"margin-top:8px;\">\n          <select id=\"subSeqAlarmTestSelect\">\n            <option value=\"1\">Alarm Seq. 1 - 초기화</option>\n            <option value=\"2\">Alarm Seq. 2 - 이어서 재진행</option>\n            <option value=\"3\">Alarm Seq. 3 - SHUTDOWN</option>\n          </select>\n          <button type=\"button\" class=\"progress-aux-btn\" id=\"subSeqAlarmTestBtn\" style=\"margin:0;\">알람 발생(TEST)</button>\n        </div>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","압력조정.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>압력조정 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 압력조정\" 화면 분리 파일. \"조정모드\" 화면(압력 조정 모드.html)의\n     \"압력조정\" 버튼으로 들어온다(Operation.js의 adjustModePressureBtn). PT/Weight 센서의\n     아날로그 원시값을 실제 공학단위 값으로 환산하는 MAX/분해능/OFFSET을 편집하는 화면 -\n     아직 실제 아날로그 배선 전이라 \"ANALOG VALUE1\"(0~분해능 카운트)은 사용자가 직접\n     입력하는 테스트값이다. \"ANALOG VALUE2\"(mA/V)는 분해능+ANALOG VALUE1만으로 계산하는\n     읽기 전용 계측기 환산값(4.00~20.00mA와 1.000~5.000V는 같은 0~100% 신호를 표현하는\n     방식이라 동시에 보여준다 - 별도 입력/타입 선택 불필요). \"현재값\"의 공학단위 환산 공식은\n     그대로 ANALOG VALUE1/분해능 비율을 쓴다. 스타일은 ../gms.css를 그대로 참조. gms.js가\n     fetch해서 id=\"progressPressureAdjustBody\" 컨테이너에 주입하고,\n     public/gms-pt-calibration.js가 표 렌더링/탭 전환/키패드 입력/열 너비 조절/저장을\n     전담한다(gms-sequence-editor.js와 같은 관심사 분리 패턴). -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressPressureAdjustBody\">\n    <div class=\"progress-menu-desc\">아날로그 센서 값을 실제 단위로 환산하는 MAX·분해능·OFFSET을 편집합니다.</div>\n    <div class=\"pt-calib-tabs\">\n      <button type=\"button\" class=\"pt-calib-tab\" id=\"ptCalibTab1Btn\"></button>\n      <button type=\"button\" class=\"pt-calib-tab\" id=\"ptCalibTab2Btn\"></button>\n    </div>\n    <div class=\"pt-calib-table-wrap\">\n      <table class=\"grid-table pt-calib-table\">\n        <thead>\n          <tr>\n            <th></th>\n            <th>MAX값</th>\n            <th>분해능</th>\n            <th>ANALOG VALUE1</th>\n            <th>ANALOG VALUE2</th>\n            <th>현재값</th>\n            <th>OFFSET VALUE</th>\n          </tr>\n        </thead>\n        <tbody id=\"ptCalibTableBody\"></tbody>\n      </table>\n      <div class=\"pt-calib-empty\" id=\"ptCalibEmptyMsg\" style=\"display:none;\">이 탭에는 아직 등록된 센서가 없습니다.</div>\n    </div>\n\n    <div class=\"pt-calib-keypad-wrap\" id=\"ptCalibKeypadWrap\" style=\"display:none;\">\n      <div class=\"pt-calib-keypad-title\" id=\"ptCalibKeypadTitle\"></div>\n      <div class=\"password-display\" id=\"ptCalibKeypadDisplay\"></div>\n      <div class=\"password-keypad pt-calib-keypad\">\n        <button type=\"button\" class=\"keypad-btn\" data-key=\"7\">7</button>\n        <button type=\"button\" class=\"keypad-btn\" data-key=\"8\">8</button>\n        <button type=\"button\" class=\"keypad-btn\" data-key=\"9\">9</button>\n        <button type=\"button\" class=\"keypad-btn keypad-aux\" data-key=\"up\">▲</button>\n        <button type=\"button\" class=\"keypad-btn\" data-key=\"4\">4</button>\n        <button type=\"button\" class=\"keypad-btn\" data-key=\"5\">5</button>\n        <button type=\"button\" class=\"keypad-btn\" data-key=\"6\">6</button>\n        <button type=\"button\" class=\"keypad-btn keypad-aux\" data-key=\"down\">▼</button>\n        <button type=\"button\" class=\"keypad-btn\" data-key=\"1\">1</button>\n        <button type=\"button\" class=\"keypad-btn\" data-key=\"2\">2</button>\n        <button type=\"button\" class=\"keypad-btn\" data-key=\"3\">3</button>\n        <button type=\"button\" class=\"keypad-btn keypad-aux\" data-key=\"bs\">BS</button>\n        <button type=\"button\" class=\"keypad-btn\" data-key=\"0\">0</button>\n        <button type=\"button\" class=\"keypad-btn\" data-key=\".\">.</button>\n        <button type=\"button\" class=\"keypad-btn\" data-key=\"-\">-</button>\n        <button type=\"button\" class=\"keypad-btn keypad-aux\" data-key=\"clear\">CLEAR</button>\n        <button type=\"button\" class=\"keypad-btn keypad-aux\" data-key=\"esc\" style=\"grid-column: span 2;\">ESC</button>\n        <button type=\"button\" class=\"keypad-btn keypad-aux primary\" data-key=\"enter\" style=\"grid-column: span 2;\">ENTER</button>\n      </div>\n    </div>\n\n    <div class=\"progress-btn-group\">\n      <div class=\"adjust-mode-actions\">\n        <button type=\"button\" class=\"progress-btn\" id=\"ptCalibSaveBtn\" style=\"margin:0;\">저장</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"ptCalibCancelBtn\" style=\"margin:0;\">취소</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","에러 사항.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>에러사항 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"에러사항\" 화면 분리 파일. 보조 메뉴의 \"📢 에러사항\" 버튼으로 들어온다\n     (Operation.js의 auxMenuErrorLogBtn/showProgressErrorLog). \"작업이력\" 화면(작업이력.html)과\n     완전히 같은 구조(Univer 그리드, A/B 탭, 기간 필터, Data Clear, 엑셀 내보내기, 복귀, 열폭\n     자동맞춤)이지만 DB는 별개(error_log 테이블)다(요청사항). public/gms-sub-sequence-runner.js가\n     서브시퀀스(조정모드 등)에서 실제 Alarm Seq. 동작(초기화/이어서재진행/SHUTDOWN)을 수행할\n     때만 기록한다 - Alarm Goto로 가볍게 다른 Step으로 이동하는 반복문/Option 분기는 알람이\n     아니므로 여기 안 남는다(그 Step 자신의 엑셀 Alarm Seq. 열이 비어있으면 기록 안 됨). 열\n     구성(왼쪽부터): 시각 / HTML화면 / Step / 측 / 조작자 / 권한 / Alarm Seq. / 알람 메시지 /\n     누적시간(초) / PT·Weight·히터 센서 개별 열(작업이력 화면과 동일한 OPTION 반영 규칙).\n     작업이력과 달리 \"구분\"(터치키/자동진행) 열과 구분 필터가 없다 - 이 화면의 행은 전부\n     서브시퀀스 알람이라 구분이 필요 없다. 이 화면도 배관도를 숨기고 그리드가 화면 전체\n     폭을 쓴다(Operation.js의 FULL_WIDTH_SCREENS 참고) - \"닫기\"를 눌러야 배관도가 돌아온다.\n     스타일은 ../gms.css를 그대로 참조. gms.js가 fetch해서 id=\"progressErrorLogBody\" 컨테이너에\n     주입하고, public/gms-errorlog-widget.js가 표 렌더링/탭 전환/열너비+행높이 조절/엑셀\n     내보내기/행별 \"복귀\"를 전담한다(gms-worklog-widget.js와 같은 관심사 분리 패턴). -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressErrorLogBody\">\n    <div class=\"progress-menu-desc\">서브시퀀스(조정모드 등)에서 실제 알람(Alarm Seq. 초기화/이어서재진행/SHUTDOWN)이 발생할 때마다 자동으로 기록됩니다.</div>\n    <div class=\"pt-calib-tabs\">\n      <button type=\"button\" class=\"pt-calib-tab\" id=\"errorLogTabABtn\">에러사항 A</button>\n      <button type=\"button\" class=\"pt-calib-tab\" id=\"errorLogTabBBtn\">에러사항 B</button>\n    </div>\n    <div class=\"trend-range-row\">\n      <label>시작 <input type=\"datetime-local\" id=\"errorLogFromInput\" step=\"1\" /></label>\n      <label>종료 <input type=\"datetime-local\" id=\"errorLogToInput\" step=\"1\" /></label>\n      <button type=\"button\" class=\"trend-toolbar-btn\" id=\"errorLogFilterBtn\">🔍 기간 조회</button>\n      <button type=\"button\" class=\"trend-toolbar-btn\" id=\"errorLogFilterResetBtn\">전체보기</button>\n    </div>\n    <div style=\"display:flex; gap:8px; margin-bottom:8px; flex-wrap:wrap;\">\n      <button type=\"button\" id=\"errorLogRefreshBtn\">🔄 새로고침</button>\n      <button type=\"button\" id=\"errorLogReturnBtn\" class=\"primary\">↩ 선택한 행 화면으로 복귀</button>\n      <button type=\"button\" id=\"errorLogDataClearBtn\" title=\"PASSWORD 확인 후 지금 탭(A/B)의 화면만 지웁니다. 서버 DB 기록은 지워지지 않고, 새로고침/기간조회로 언제든 다시 불러올 수 있습니다.\">🧹 Data Clear</button>\n      <button type=\"button\" id=\"errorLogExcelExportBtn\">📤 엑셀로 내보내기</button>\n      <button type=\"button\" id=\"errorLogCloseBtn\" style=\"margin-left:auto;\">✕ 닫기</button>\n    </div>\n    <div id=\"gmsErrorLogGridContainer\" style=\"flex:1 1 400px; min-height:400px; width:100%; position:relative; overflow:hidden; background:#fff;\"></div>\n    <div class=\"h-splitter\" id=\"gmsErrorLogGridResizeHandle\" title=\"드래그해서 그리드 높이 조절\"></div>\n  </div>\n</body>\n</html>\n","용기교체CC_Auto Guard Close 확인.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Auto Guard 확인(Close) - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 자동 진행\" 화면 분리 파일 - 용기교체(Status \"CC\") 6단계 중\n     여섯(현재 마지막) 번째, \"Gas name 확인\" 다음. 실린더 재장착 후 Auto Guard가 Close\n     되었는지 확인하는 화면 - 앞서 나온 \"Auto Guard 확인(Open)\"과 이름은 같지만 파일/\n     컨테이너는 분리해 둔다(문구·역할이 다름). 화면 진입 시 Operation.js의 applyCcStepValves가\n     CylReplace_v1.json Step6을 읽어 SVG 배관도에 반영한다(AG_{side}/PIV는 즉시 Close,\n     PGII_{side}/PGI_{side}는 2초 간격으로 순차 Close, 텍스트 배지 아님) - \"확인\"을 누르면\n     용기교체 완료 토스트 후 실린더 잠금 check로 되돌아간다(교환후 - +L 이후 - 시퀀스는\n     아직 없어 Status는 CC에 그대로 둔다). \"취소\"는 용기교체를 그만두고 Status를 2P로\n     되돌린 뒤 실린더 잠금 check로 나간다. 스타일은 ../gms.css를 그대로 참조(복사 아님).\n     gms.js가 fetch해서 id=\"progressCylReplaceAutoGuardCloseBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressCylReplaceAutoGuardCloseBody\">\n    <div class=\"barcode-check-title\">[ Auto Guard 확인 ]</div>\n    <div class=\"progress-menu-desc\">실린더 교체를 위한<br>Auto Guard와 Valve가<br>순차적으로 Close 됩니다.</div>\n    <div class=\"progress-btn-group\">\n      <div style=\"display:flex;gap:10px;\">\n        <button type=\"button\" class=\"progress-btn\" id=\"cylReplaceAutoGuardCloseConfirmBtn\" style=\"flex:1;margin-bottom:0;\">확인</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"cylReplaceAutoGuardCloseCancelBtn\" style=\"flex:1;margin-top:0;\">취소</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","용기교체CC_Auto Guard Open 확인.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Auto Guard 확인(Open) - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 자동 진행\" 화면 분리 파일 - 용기교체(Status \"CC\") 6단계 중\n     세 번째, \"Valve Open 확인\" 다음. 실린더 분리 전 Auto Guard가 Open 되어 있는지 확인하는\n     화면 - 뒤에 나오는 \"Auto Guard 확인(Close)\"과 이름은 같지만 파일/컨테이너는 분리해\n     둔다(문구·역할이 다름). 화면 진입 시 Operation.js의 applyCcStepValves가\n     CylReplace_v1.json Step3을 읽어 SVG 배관도의 AG_{side} 아이콘에 Open 상태를 반영한다\n     (텍스트 배지 아님) - \"확인\"은 다음 화면(실린더 분리 및 교체)으로, \"취소\"는 용기교체를\n     그만두고 Status를 2P로 되돌린 뒤\n     실린더 잠금 check로 나간다. 스타일은 ../gms.css를 그대로 참조(복사 아님). gms.js가\n     fetch해서 id=\"progressCylReplaceAutoGuardOpenBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressCylReplaceAutoGuardOpenBody\">\n    <div class=\"barcode-check-title\">[ Auto Guard 확인 ]</div>\n    <div class=\"progress-menu-desc\">실린더 교체전<br>Auto Guard가 Open<br>되었는지 확인해<br>주시기 바랍니다.</div>\n    <div class=\"progress-btn-group\">\n      <div style=\"display:flex;gap:10px;\">\n        <button type=\"button\" class=\"progress-btn\" id=\"cylReplaceAutoGuardOpenConfirmBtn\" style=\"flex:1;margin-bottom:0;\">확인</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"cylReplaceAutoGuardOpenCancelBtn\" style=\"flex:1;margin-top:0;\">취소</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","용기교체CC_Force Purge.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Force Purge - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 자동 진행\" 화면 분리 파일 - 용기교체(CC)의 \"실린더 확인\"\n     화면 \"Force Purge\" 버튼으로 들어온다. Status는 계속 CC로 그대로 둔다(다른 CC 단계들과\n     마찬가지로 배지 없음). \"수동 배관 청소\" 화면과 같은 설정/진행 횟수 구성을 재사용하되,\n     이미 자동으로 진행 중인 화면이라 \"확인\" 없이 \"취소\"만 있다. 실제 시퀀스/횟수 로직은\n     아직 없음(뼈대) - \"취소\"는 실린더 확인 화면으로 되돌아간다. 스타일은 ../gms.css를\n     그대로 참조(복사 아님). gms.js가 fetch해서 id=\"progressCylReplaceForcePurgeBody\"\n     컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressCylReplaceForcePurgeBody\">\n    <div class=\"progress-menu-desc\">수동 배관 청소<br>모드입니다.</div>\n    <div class=\"progress-menu-desc\" style=\"margin-top: 22px;\">Out Gassing 제거 중</div>\n    <div class=\"progress-btn-group\">\n      <div class=\"purge-count-panel\">\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">설정 횟수 :</span>\n          <span class=\"purge-count-box\">[ <input type=\"number\" id=\"cylReplaceForcePurgeSetCount\" class=\"purge-count-input\" min=\"0\" step=\"1\" value=\"1\" /> ]</span>\n        </div>\n        <div class=\"purge-count-row\">\n          <span class=\"purge-count-label\">진행 횟수 :</span>\n          <span class=\"purge-count-box\">[ <span id=\"cylReplaceForcePurgeProgressCount\" class=\"purge-count-value\">0</span> ]</span>\n        </div>\n      </div>\n      <button type=\"button\" class=\"progress-aux-btn\" id=\"cylReplaceForcePurgeCancelBtn\" style=\"width:100%;\">취소</button>\n    </div>\n  </div>\n</body>\n</html>\n","용기교체CC_Gas name 확인.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Gas name 확인 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 자동 진행\" 화면 분리 파일 - 용기교체(Status \"CC\") 6단계 중\n     다섯 번째, \"실린더 분리 및 교체\" 다음. \"수동 바코드 체크\" 화면과 같은 barcode-check-*\n     스타일을 재사용하되 id는 전부 별도로 둔다(같은 페이지에 두 화면이 동시에 존재하므로\n     겹치면 안 됨). 제목의 측/번호(A1 등)는 Operation.js가 progressCurrentSide에 맞춰\n     id=\"cylReplaceGasNameTitle\" 텍스트를 동적으로 바꾼다. 실제 바코드 검증/Lot No. 로직은\n     아직 없음(뼈대) - \"Lot No. Skip\"/\"바코드 수동입력\"/\"바코드 확인\"은 토스트만, \"실행\"은\n     다음 화면(Auto Guard 확인(Close))으로, \"취소\"는 용기교체를 그만두고 Status를 2P로\n     되돌린 뒤 실린더 잠금 check로 나간다. 스타일은 ../gms.css를 그대로 참조(복사 아님).\n     gms.js가 fetch해서 id=\"progressCylReplaceGasNameBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressCylReplaceGasNameBody\">\n    <div class=\"barcode-check-title\" id=\"cylReplaceGasNameTitle\">[A1 실린더 Gas name 확인]</div>\n    <div class=\"barcode-check-desc\">바코드 스캐너를 이용하여<br>실린더 바코드를 읽어 주시기 바랍니다.</div>\n    <div class=\"progress-btn-group\">\n      <div class=\"barcode-input-row\">\n        <span class=\"purge-count-label\">1</span>\n        <input type=\"text\" id=\"cylReplaceGasNameInput1\" class=\"barcode-input\" placeholder=\"바코드 스캔\" />\n      </div>\n      <div class=\"barcode-input-row\">\n        <span class=\"purge-count-label\">2</span>\n        <input type=\"text\" id=\"cylReplaceGasNameInput2\" class=\"barcode-input\" placeholder=\"바코드 스캔\" />\n      </div>\n      <div class=\"barcode-check-warn\">N.G시 담당자에게<br>연락 하시기 바랍니다.</div>\n      <button type=\"button\" class=\"progress-aux-btn\" id=\"cylReplaceGasNameLotSkipBtn\" style=\"margin-bottom:16px;\">Lot No. Skip</button>\n      <div style=\"display:flex;gap:10px;margin-bottom:10px;\">\n        <button type=\"button\" class=\"progress-btn\" id=\"cylReplaceGasNameRunBtn\" style=\"flex:1;margin-bottom:0;\">실행</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"cylReplaceGasNameCancelBtn\" style=\"flex:1;margin-top:0;\">취소</button>\n      </div>\n      <div style=\"display:flex;gap:10px;\">\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"cylReplaceGasNameManualBtn\" style=\"flex:1;\">바코드 수동입력</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"cylReplaceGasNameCheckBtn\" style=\"flex:1;\">바코드 확인</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","용기교체CC_Valve Open 확인.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Valve Open 확인 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 자동 진행\" 화면 분리 파일 - 용기교체(Status \"CC\") 6단계 중\n     두 번째, \"실린더 확인\" 화면의 \"확인\" 다음. PIV(공통)/PGI_·PGII_(측별) 태그는\n     Operation.js가 progressCurrentSide에 맞춰 id=\"cylReplaceValveOpenTagsLabel\"의 텍스트를\n     동적으로 바꾼다(기본값은 A측 표시). 실제 밸브 개폐는 화면 진입 시 Operation.js의\n     applyCcStepValves가 CylReplace_v1.json Step2를 읽어 SVG 배관도에 반영한다(PIV→PGII→PGI\n     순서로 2초 간격 Open, 텍스트 배지 아님) - \"확인\"은 다음 화면(Auto Guard 확인)으로,\n     \"취소\"는 용기교체를 그만두고 Status를 2P로 되돌린 뒤 실린더 잠금 check로 나간다.\n     스타일은 ../gms.css를 그대로 참조(복사 아님). gms.js가 fetch해서\n     id=\"progressCylReplaceValveOpenBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressCylReplaceValveOpenBody\">\n    <div class=\"barcode-check-title\">[ Valve Open 확인 ]</div>\n    <div class=\"progress-menu-desc\">실린더 교체용 Valve가<br>순차적으로 Open 됩니다.</div>\n    <div class=\"barcode-check-desc\" id=\"cylReplaceValveOpenTagsLabel\">PIV, PGII_A, PGI_A<br>2초 간격으로 순차 Open<br>진행 하시기 바랍니다.</div>\n    <div class=\"barcode-check-warn\">단, HPIV는 Close 입니다.</div>\n    <div class=\"progress-btn-group\">\n      <div style=\"display:flex;gap:10px;\">\n        <button type=\"button\" class=\"progress-btn\" id=\"cylReplaceValveOpenConfirmBtn\" style=\"flex:1;margin-bottom:0;\">확인</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"cylReplaceValveOpenCancelBtn\" style=\"flex:1;margin-top:0;\">취소</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","용기교체CC_실린더 분리 및 교체.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>실린더 분리 및 교체 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 자동 진행\" 화면 분리 파일 - 용기교체(Status \"CC\") 6단계 중\n     네 번째, \"Auto Guard 확인(Open)\" 다음. 실제 Torque Wrench/Load Cell 연동은 아직\n     없음(뼈대) - \"Load Cell Offset Zero Setting\"은 토스트만, 사용 압력 값은 참고값(550)\n     고정 표시. \"확인\"은 다음 화면(Gas name 확인)으로, \"취소\"는 용기교체를 그만두고\n     Status를 2P로 되돌린 뒤 실린더 잠금 check로 나간다. 스타일은 ../gms.css를 그대로\n     참조(복사 아님). gms.js가 fetch해서 id=\"progressCylReplaceSwapBody\" 컨테이너에\n     주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressCylReplaceSwapBody\">\n    <div class=\"barcode-check-title\">[ 실린더 분리 및 교체 ]</div>\n    <div class=\"progress-menu-desc\">이전 실린더를 분리하고,<br>새로운 실린더를<br>장착하십시오.<br>CGA Connector에<br>연결시 Torque Wrench<br>사용 압력을 확인하시기<br>바랍니다.</div>\n    <div class=\"purge-count-panel\">\n      <div class=\"purge-count-row\">\n        <span class=\"purge-count-label\">Torque Wrench<br>사용 압력 :</span>\n        <span class=\"purge-count-box\">[ <input type=\"number\" id=\"cylReplaceSwapTorqueValue\" class=\"purge-count-input\" style=\"width:56px;color:var(--error);\" min=\"0\" step=\"1\" value=\"550\" /> ]Kgf</span>\n      </div>\n    </div>\n    <div class=\"progress-btn-group\">\n      <button type=\"button\" class=\"progress-aux-btn\" id=\"cylReplaceSwapZeroBtn\" style=\"margin-bottom:22px;\">Load Cell Offset<br>Zero Setting</button>\n      <div style=\"display:flex;gap:10px;\">\n        <button type=\"button\" class=\"progress-btn\" id=\"cylReplaceSwapConfirmBtn\" style=\"flex:1;margin-bottom:0;\">확인</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"cylReplaceSwapCancelBtn\" style=\"flex:1;margin-top:0;\">취소</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","용기교체CC_실린더 확인.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>실린더 확인 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 자동 진행\" 화면 분리 파일 - PASSWORD(\"실린더 교체\") 통과\n     후 들어오는 \"용기교체\"(Status \"CC\") 6단계 중 첫 번째 화면. 이 단계들은 배지(step-badges-lg)\n     없이 안내문/버튼만 보여준다(참고 사진에 배지가 없음). 실제 시퀀스/검증 로직은 아직\n     없음(뼈대) - \"준비전 모드변경\"/\"Force Purge\"는 토스트만, \"확인\"은 다음 화면(Valve\n     Open 확인)으로, \"취소\"는 용기교체 자체를 그만두고 Status를 2P로 되돌린 뒤 실린더\n     잠금 check로 나간다. 스타일은 ../gms.css를 그대로 참조(복사 아님). gms.js가 fetch해서\n     id=\"progressCylReplaceCheckBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressCylReplaceCheckBody\">\n    <div class=\"barcode-check-title\">[ 실린더 확인 ]</div>\n    <div class=\"progress-menu-desc\">실린더의 충진 일자를<br>확인해 주시기 바랍니다.</div>\n    <div class=\"progress-btn-group\">\n      <button type=\"button\" class=\"progress-aux-btn\" id=\"cylReplaceCheckModeBtn\" style=\"margin-bottom:12px;\">준비전 모드변경</button>\n      <button type=\"button\" class=\"progress-aux-btn\" id=\"cylReplaceCheckForcePurgeBtn\" style=\"margin-bottom:22px;\">Force Purge</button>\n      <div style=\"display:flex;gap:10px;\">\n        <button type=\"button\" class=\"progress-btn\" id=\"cylReplaceCheckConfirmBtn\" style=\"flex:1;margin-bottom:0;\">확인</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"cylReplaceCheckCancelBtn\" style=\"flex:1;margin-top:0;\">취소</button>\n      </div>\n      <!-- CC 6화면 전체의 밸브 순서 데이터를 이 화면에서 엑셀로 내보내서 편집하고,\n           편집한 파일을 다시 불러와 그대로 반영한다(gms-sub-sequence-runner.js의\n           subSeqWireExcelButtons 재사용 - Operation.js wireOperationScreens 참고). -->\n      <div class=\"adjust-mode-actions\" style=\"margin-top:8px;\">\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"cylReplaceCheckExcelExportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 내보내기</button>\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"cylReplaceCheckExcelImportBtn\" style=\"margin:0;\">서브시퀀스 엑셀 불러오기</button>\n      </div>\n      <input type=\"file\" id=\"cylReplaceCheckExcelFileInput\" accept=\".xlsx\" style=\"display:none;\" />\n    </div>\n  </div>\n</body>\n</html>\n","유지보수 메뉴.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>유지보수 메뉴 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 유지보수 메뉴\" 화면 분리 파일. 스타일은 ../gms.css를 그대로\n     참조(복사 아님). gms.js가 fetch해서 id=\"progressMaintenanceMenuBody\" 컨테이너에 주입한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <!-- PASSWORD 통과 후 나타나는 유지보수 메뉴 - 메뉴얼(\"Main_Menu(유지보수)\" 시트)의\n       [유지보수 메뉴] 하위 항목 중 우선 3개(수동밸브조작/바코드 체크/Maintenance\n       Purge)만 먼저 만든다. 실제 동작은 아직 없음(뼈대) - 화면 전환(취소)만 동작. -->\n  <div class=\"progress-menu-body\" id=\"progressMaintenanceMenuBody\">\n    <div class=\"progress-menu-desc\">유지보수 항목을 선택하십시오.</div>\n    <div class=\"progress-btn-group\">\n      <button type=\"button\" class=\"progress-btn\" id=\"maintenanceMenuManualValveBtn\" data-action=\"수동밸브 조작\">수동밸브 조작</button>\n      <button type=\"button\" class=\"progress-btn\" id=\"maintenanceMenuBarcodeBtn\" data-action=\"바코드 체크\">바코드 체크</button>\n      <button type=\"button\" class=\"progress-btn\" id=\"maintenanceMenuPurgeBtn\" data-action=\"Maintenance Purge\">Maintenance Purge</button>\n      <div style=\"display:flex;gap:10px;margin-top:14px;\">\n        <button type=\"button\" class=\"progress-aux-btn\" id=\"maintenanceMenuCancelBtn\" style=\"flex:1;\">취소</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","유지보수모드.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>유지보수모드 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"유지보수모드\" 화면 분리 파일. 보조 메뉴의 \"유지보수모드\" 버튼으로\n     PASSWORD(게이트 키 'auxMaintenanceMode')를 통과한 뒤 들어온다(Operation.js의\n     window.requestAuxMaintenanceMode/showProgressAuxMaintenanceMode). 기존 조작화면의\n     \"유지 보수\"(메인 메뉴 → 수동밸브조작/바코드체크/Maintenance Purge)와는 완전히 다른\n     화면이다 - 여기서는 PM Mode/Set-up Mode 두 가지를 적용/미적용으로 켜고 끌 수 있다.\n     PM Mode: shutdown 알람센서 Test 중 실제로 장비가 shutdown 되지 않게 하는 목적.\n     Set-up Mode: GMS 모니터링이 상위로 올리는 통신 프로토콜 중 Alarm 항목을 차단하는 목적.\n     상태는 서버(gmsManager.js gmsState.pmMode/setupMode)가 들고 있고 웹소켓으로 모든\n     클라이언트에 방송되므로, 배관도 램프(.diagram-mode-lamps)와 Cylinder Step Status의\n     etc 행(PM/SETUP 버튼)도 함께 즉시 갱신된다. 스타일은 ../gms.css를 그대로 참조. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressAuxMaintenanceModeBody\">\n    <div class=\"progress-menu-desc\">\n      기존 조작화면의 \"유지 보수\"와는 별개의 화면입니다. PM Mode/Set-up Mode를 켜고 끌 수 있습니다.\n    </div>\n    <div class=\"aux-maint-mode-row\">\n      <div class=\"aux-maint-mode-label\">\n        <div class=\"aux-maint-mode-title\">PM Mode</div>\n        <div class=\"aux-maint-mode-desc\">shutdown 알람센서 Test 중 장비가 실제로 shutdown 되지 않도록 합니다.</div>\n      </div>\n      <button type=\"button\" id=\"pmModeToggleBtn\" class=\"aux-maint-mode-toggle\"></button>\n    </div>\n    <div class=\"aux-maint-mode-row\">\n      <div class=\"aux-maint-mode-label\">\n        <div class=\"aux-maint-mode-title\">Set-up Mode</div>\n        <div class=\"aux-maint-mode-desc\">GMS 모니터링이 상위로 올리는 통신 프로토콜 중 Alarm 항목을 차단합니다.</div>\n      </div>\n      <button type=\"button\" id=\"setupModeToggleBtn\" class=\"aux-maint-mode-toggle\"></button>\n    </div>\n    <div class=\"progress-btn-group\">\n      <button type=\"button\" class=\"progress-btn\" id=\"auxMaintenanceModeCloseBtn\">◀ 이전화면</button>\n    </div>\n  </div>\n</body>\n</html>\n","작업이력.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>작업이력 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"작업이력\" 화면 분리 파일. 보조 메뉴의 \"작업이력\" 버튼으로 들어온다\n     (Operation.js의 auxMenuWorkLogBtn/showProgressWorkLog). 조작화면에서 실행/확인류 버튼을\n     누를 때마다 Operation.js의 logWorkAction()이 서버(src/gmsHistory.js work_log 테이블)에\n     기록한 내용과, public/gms-sub-sequence-runner.js가 서브시퀀스 Step이 바뀔 때마다 남기는\n     자동진행 이력을 같은 표에 시간순으로 함께 보여준다(별도 DB 없이 work_log 확장 - \"터치키\n     이력 + 자동진행 이력을 한 화면에서 보고 싶다\" 요청에 따른 설계). 열 구성(왼쪽부터):\n     구분(터치키/자동진행) / HTML화면(제목) / 조작 Key / 측(그 순간 그 측의 Status 상태 메시지,\n     예 \"[A] 실린더 교체\") / 시각 / 조작자 / 권한 / 자동진행 Step / 자동진행 누적(초) /\n     PT·Weight 센서 개별 열(VT/VPT/FPT/LPT_x/NPT_x/HPT_x/WI_x) - 조작자는 PASSWORD로 확인된\n     사람, 비번 없이 누른 키는 마지막 확인자를 그대로 이어받는다(자동진행 행은 조작자 없이\n     기록됨). A/B 탭으로 나뉘고 공통(양측 공용) 조작은 두 탭 모두에 표시되며, 전체/자동진행만/\n     터치조작만 라디오 그룹으로 둘 중 하나만 걸러 볼 수 있다. 이 화면만 배관도(.diagram-panel)를 숨기고\n     그리드가 화면 전체 폭을 쓴다(14개 안팎의 열이라 좁은 우측 패널만으론 비좁음 -\n     Operation.js의 setWorkLogFullWidth 참고) - \"닫기\"를 눌러야 배관도가 돌아온다. 스타일은\n     ../gms.css를 그대로 참조. gms.js가 fetch해서 id=\"progressWorkLogBody\" 컨테이너에\n     주입하고, public/gms-worklog-widget.js가 표 렌더링/탭 전환/열너비+행높이 조절/엑셀\n     내보내기/행별 \"복귀\"를 전담한다(gms-user-widget.js와 같은 관심사 분리 패턴). -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressWorkLogBody\">\n    <div class=\"progress-menu-desc\">조작화면에서 실행/확인 버튼을 누를 때마다 자동으로 기록됩니다.</div>\n    <div class=\"pt-calib-tabs\">\n      <button type=\"button\" class=\"pt-calib-tab\" id=\"workLogTabABtn\">작업이력 A</button>\n      <button type=\"button\" class=\"pt-calib-tab\" id=\"workLogTabBBtn\">작업이력 B</button>\n    </div>\n    <div class=\"trend-range-row\">\n      <label>시작 <input type=\"datetime-local\" id=\"workLogFromInput\" step=\"1\" /></label>\n      <label>종료 <input type=\"datetime-local\" id=\"workLogToInput\" step=\"1\" /></label>\n      <button type=\"button\" class=\"trend-toolbar-btn\" id=\"workLogFilterBtn\">🔍 기간 조회</button>\n      <button type=\"button\" class=\"trend-toolbar-btn\" id=\"workLogFilterResetBtn\">전체보기</button>\n      <!-- 터치키 조작이력과 서브시퀀스(자동진행) Step 이력이 같은 표에 함께 기록되므로,\n           둘 중 하나만 걸러 보고 싶을 때 쓴다(gms-worklog-widget.js) - 셋 중 하나만 켜지는\n           라디오 그룹(전체/자동진행만/터치조작만), 체크박스 2개를 따로 두면 둘 다 켜졌을 때\n           의미가 모호해지므로 상호배타로 만들었다. -->\n      <span style=\"display:flex; align-items:center; gap:10px;\">\n        <label style=\"display:flex; align-items:center; gap:4px;\"><input type=\"radio\" name=\"workLogKindFilter\" id=\"workLogKindFilterAll\" value=\"all\" checked /> 전체</label>\n        <label style=\"display:flex; align-items:center; gap:4px;\"><input type=\"radio\" name=\"workLogKindFilter\" id=\"workLogKindFilterAuto\" value=\"auto\" /> 자동진행만</label>\n        <label style=\"display:flex; align-items:center; gap:4px;\"><input type=\"radio\" name=\"workLogKindFilter\" id=\"workLogKindFilterTouch\" value=\"touch\" /> 터치조작만</label>\n      </span>\n    </div>\n    <div style=\"display:flex; gap:8px; margin-bottom:8px; flex-wrap:wrap;\">\n      <button type=\"button\" id=\"workLogRefreshBtn\">🔄 새로고침</button>\n      <button type=\"button\" id=\"workLogReturnBtn\" class=\"primary\">↩ 선택한 행 화면으로 복귀</button>\n      <button type=\"button\" id=\"workLogDataClearBtn\" title=\"PASSWORD 확인 후 지금 탭(A/B)의 화면만 지웁니다. 서버 DB 기록은 지워지지 않고, 새로고침/기간조회로 언제든 다시 불러올 수 있습니다.\">🧹 Data Clear</button>\n      <button type=\"button\" id=\"workLogExcelExportBtn\">📤 엑셀로 내보내기</button>\n      <button type=\"button\" id=\"workLogMsgExportBtn\">📤 메시지 설정 내보내기</button>\n      <button type=\"button\" id=\"workLogMsgImportBtn\">📥 메시지 설정 불러오기</button>\n      <input type=\"file\" id=\"workLogMsgImportFile\" accept=\".xlsx\" hidden />\n      <button type=\"button\" id=\"workLogTitleExportBtn\" title=\"A열(HTML화면)에 찍히는 화면 제목을 엑셀로 내보냅니다\">📤 화면 제목 내보내기</button>\n      <button type=\"button\" id=\"workLogTitleImportBtn\" title=\"엑셀로 편집한 화면 제목을 불러와 반영합니다\">📥 화면 제목 불러오기</button>\n      <input type=\"file\" id=\"workLogTitleImportFile\" accept=\".xlsx\" hidden />\n      <button type=\"button\" id=\"workLogCloseBtn\" style=\"margin-left:auto;\">✕ 닫기</button>\n    </div>\n    <div id=\"gmsWorkLogGridContainer\" style=\"flex:1 1 400px; min-height:400px; width:100%; position:relative; overflow:hidden; background:#fff;\"></div>\n    <div class=\"h-splitter\" id=\"gmsWorkLogGridResizeHandle\" title=\"드래그해서 그리드 높이 조절\"></div>\n  </div>\n</body>\n</html>\n","진행 메뉴.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>진행 메뉴 - GMS 조작화면</title>\n<!-- gms.html의 조작화면(진행 메뉴 패널) 중 \"진행 메뉴\" 화면만 분리한 파일이다.\n     스타일은 gms.html이 쓰는 공용 스타일시트(../gms.css)를 그대로 참조하며 복사하지 않는다 -\n     이 파일에서 색/여백을 바꾸면 gms.html에도 그대로 반영된다.\n     gms.js가 페이지 로드 시 이 파일을 fetch해서 id=\"progressRootBody\" 컨테이너의\n     내용물로 그대로 주입한다 - id/class는 gms.js의 기존 로직과 맞물려 있으므로 유지해야 한다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <div class=\"progress-menu-body\" id=\"progressRootBody\">\n    <div class=\"progress-menu-desc\">진행할 메뉴를 선택하십시오.</div>\n    <!-- 버튼 묶음은 프레임 맨 아래에 붙고, 그 안에서 아래→위 순서로 쌓인다\n         (margin-top:auto로 남는 세로 공간을 위쪽으로 밀어냄). -->\n    <div class=\"progress-btn-group\">\n      <button type=\"button\" class=\"progress-btn\" id=\"progressABtn\">A 진행</button>\n      <button type=\"button\" class=\"progress-btn\" id=\"progressBBtn\">B 진행</button>\n      <button type=\"button\" class=\"progress-aux-btn\" id=\"progressAuxBtn\">보조 메뉴</button>\n    </div>\n  </div>\n</body>\n</html>\n","히터 조작.html":"<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>히터 조작 - GMS 조작화면</title>\n<!-- gms.html 조작화면 중 \"[A/B] 히터 조작\" 화면 분리 파일. 스타일은 ../gms.css를 그대로\n     참조(복사 아님). gms.js가 fetch해서 id=\"progressHeaterBody\" 컨테이너에 주입한 뒤,\n     renderHeaterGrid()가 #manualHeaterGrid 안을 실제 히터 버튼으로 채운다. -->\n<link rel=\"stylesheet\" href=\"../gms.css\">\n</head>\n<body>\n  <!-- 히터 조작 - 수동밸브 조작 화면의 H/T 버튼으로 들어온다. M/H(매니폴드 히터)・\n       J/H(재킷 히터)・L/H_2nd(2차 배관 히터) 3종을 다루며, 전부 A/B 양쪽 각각 존재한다.\n       밸브와 동일한 방식(점멸+확인+쓰기)으로 동작하고, 격자 크기(3열×5행)도 수동밸브\n       조작 화면과 맞춰뒀다(나머지 칸은 향후 히터 확장 자리로 비워둠). V/V 버튼으로 밸브\n       화면으로 돌아간다(서로 왔다갔다 가능). -->\n  <div class=\"progress-menu-body\" id=\"progressHeaterBody\">\n    <div class=\"valve-grid-layout\">\n      <div class=\"valve-grid\" id=\"manualHeaterGrid\"></div>\n      <div class=\"valve-grid-side-actions\">\n        <button type=\"button\" class=\"valve-side-btn\" id=\"heaterQcBtn\" style=\"flex:2;\">Q<br>/<br>C</button>\n        <button type=\"button\" class=\"valve-side-btn\" id=\"heaterCancelBtn\" style=\"flex:2;\">취소</button>\n        <button type=\"button\" class=\"valve-side-btn primary\" id=\"heaterConfirmBtn\" style=\"flex:1;\">확인</button>\n        <button type=\"button\" class=\"valve-side-btn\" id=\"heaterToValveBtn\" style=\"flex:1;\">V/V</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n"};
